const DeadlineBadge = ({ deadline, deadlineTime }) => {
  if (!deadline) return null;
  const d = new Date(deadline + "T00:00:00");
  const diffDays = Math.floor((d - new Date(today() + "T00:00:00")) / 86400000);
  const label = `${d.getMonth()+1}/${d.getDate()}${deadlineTime ? " " + deadlineTime : ""}`;
  const isOverdue = diffDays < 0;
  const isToday   = diffDays === 0;
  const isSoon    = diffDays > 0 && diffDays <= 3;
  const color = isOverdue ? "#EF4444" : isToday ? "#F97316" : isSoon ? "#F59E0B" : "#6B7280";
  const bg    = isOverdue ? "#FEF2F2" : isToday ? "#FFF7ED" : isSoon ? "#FFFBEB" : "#F3F4F6";
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 2, background: bg, color, borderRadius: 20, padding: "2px 7px", fontSize: 10, fontWeight: 600, whiteSpace: "nowrap" }}>
      {deadlineTime ? "⏰" : "📅"} {label}まで
    </span>
  );
};

const sortByDeadlineTime = (todos) => {
  const todayStr = today();
  return [...todos].sort((a, b) => {
    const aTime = a.deadline === todayStr && a.deadlineTime ? a.deadlineTime : null;
    const bTime = b.deadline === todayStr && b.deadlineTime ? b.deadlineTime : null;
    if (aTime && bTime) return aTime.localeCompare(bTime);
    if (aTime) return -1;
    if (bTime) return 1;
    return 0;
  });
};

