// ─── DRUM PICKER (繰り返し時刻設定) ──────────────────────────────────────────
const DrumPicker = ({ value = "08:00", onChange, th }) => {
  const initH = parseInt(value.split(":")[0]) || 8;
  const initMRaw = parseInt(value.split(":")[1]) || 0;
  const initM = Math.round(initMRaw / 5) * 5;
  const HOURS = Array.from({ length: 24 }, (_, i) => i);
  const MINS  = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55];
  const ITEM_H = 44;

  const selHRef = useRef(initH);
  const selMRef = useRef(MINS.includes(initM) ? initM : 0);
  const hRef    = useRef(null);
  const mRef    = useRef(null);
  const hTimer  = useRef(null);
  const mTimer  = useRef(null);

  useEffect(() => {
    if (hRef.current) hRef.current.scrollTop = initH * ITEM_H;
    if (mRef.current) {
      const mIdx = [0,5,10,15,20,25,30,35,40,45,50,55].indexOf(selMRef.current);
      mRef.current.scrollTop = (mIdx >= 0 ? mIdx : 0) * ITEM_H;
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const onHScroll = () => {
    clearTimeout(hTimer.current);
    hTimer.current = setTimeout(() => {
      if (!hRef.current) return;
      const idx = Math.min(Math.max(Math.round(hRef.current.scrollTop / ITEM_H), 0), HOURS.length - 1);
      selHRef.current = HOURS[idx];
      hRef.current.scrollTo({ top: idx * ITEM_H, behavior: "smooth" });
      onChange(`${String(selHRef.current).padStart(2,"0")}:${String(selMRef.current).padStart(2,"0")}`);
    }, 120);
  };
  const onMScroll = () => {
    clearTimeout(mTimer.current);
    mTimer.current = setTimeout(() => {
      if (!mRef.current) return;
      const idx = Math.min(Math.max(Math.round(mRef.current.scrollTop / ITEM_H), 0), MINS.length - 1);
      selMRef.current = MINS[idx];
      mRef.current.scrollTo({ top: idx * ITEM_H, behavior: "smooth" });
      onChange(`${String(selHRef.current).padStart(2,"0")}:${String(selMRef.current).padStart(2,"0")}`);
    }, 120);
  };

  const primary = th?.primary || "#059669";
  const colStyle = { flex: 1, height: ITEM_H * 5, overflowY: "scroll", scrollSnapType: "y mandatory", WebkitOverflowScrolling: "touch", scrollbarWidth: "none" };
  const itemStyle = (sel) => ({ height: ITEM_H, display: "flex", alignItems: "center", justifyContent: "center", scrollSnapAlign: "center", fontSize: 22, fontWeight: sel ? 700 : 400, color: sel ? "#111827" : "#D1D5DB", transition: "color 0.1s" });

  return (
    <div style={{ borderRadius: 14, overflow: "hidden", border: `1.5px solid ${th?.border || "#E5E7EB"}`, background: th?.bg || "#F9FAFB", position: "relative", userSelect: "none" }}>
      <div style={{ position: "absolute", top: "50%", left: 0, right: 0, height: ITEM_H, transform: "translateY(-50%)", background: `${primary}12`, borderTop: `1.5px solid ${primary}60`, borderBottom: `1.5px solid ${primary}60`, pointerEvents: "none", zIndex: 2 }} />
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: ITEM_H * 2, background: `linear-gradient(to bottom, ${th?.bg || "#F9FAFB"} 10%, transparent)`, pointerEvents: "none", zIndex: 3 }} />
      <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: ITEM_H * 2, background: `linear-gradient(to top, ${th?.bg || "#F9FAFB"} 10%, transparent)`, pointerEvents: "none", zIndex: 3 }} />
      <div style={{ display: "flex", alignItems: "center" }}>
        <div ref={hRef} onScroll={onHScroll} style={colStyle}>
          <div style={{ height: ITEM_H * 2 }} />
          {HOURS.map(h => <div key={h} style={itemStyle(h === selHRef.current)}>{String(h).padStart(2,"0")}</div>)}
          <div style={{ height: ITEM_H * 2 }} />
        </div>
        <div style={{ width: 28, textAlign: "center", fontSize: 22, fontWeight: 700, color: th?.text || "#374151", position: "relative", zIndex: 4, flexShrink: 0 }}>:</div>
        <div ref={mRef} onScroll={onMScroll} style={colStyle}>
          <div style={{ height: ITEM_H * 2 }} />
          {MINS.map(m => <div key={m} style={itemStyle(m === selMRef.current)}>{String(m).padStart(2,"0")}</div>)}
          <div style={{ height: ITEM_H * 2 }} />
        </div>
      </div>
    </div>
  );
};

// ─── DOPAMINE CIRCLE ──────────────────────────────────────────────────────────
// eslint-disable-next-line no-unused-vars
const DopamineCircle = ({ score, th }) => {
  const R = 50, SIZE = 130, C = 65;
  const circumference = 2 * Math.PI * R;
  const offset = circumference - (score / 100) * circumference;
  const color = score >= 80 ? "#10B981" : score >= 60 ? "#3B82F6" : score >= 40 ? "#F59E0B" : "#EF4444";
  const title = TITLE_SYSTEM.find(t => score >= t.minScore) || TITLE_SYSTEM[TITLE_SYSTEM.length - 1];
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <div style={{ position: "relative", width: SIZE, height: SIZE }}>
        <svg width={SIZE} height={SIZE} style={{ transform: "rotate(-90deg)" }}>
          <circle cx={C} cy={C} r={R} fill="none" stroke={th?.border || "#E5E7EB"} strokeWidth={10} />
          <circle cx={C} cy={C} r={R} fill="none" stroke={color} strokeWidth={10}
            strokeDasharray={circumference} strokeDashoffset={offset} strokeLinecap="round"
            style={{ transition: "stroke-dashoffset 1s ease, stroke 0.5s" }} />
        </svg>
        <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
          <span style={{ fontSize: 26, fontWeight: 800, color: th?.text || "#111827", lineHeight: 1 }}>{score}</span>
          <span style={{ fontSize: 9, color: th?.subtext || "#6B7280", marginTop: 2 }}>スコア</span>
        </div>
      </div>
      <div style={{ fontSize: 11, fontWeight: 700, color, marginTop: -4 }}>{title.title}</div>
    </div>
  );
};

// ─── WEEKLY SCORE CHART ───────────────────────────────────────────────────────
// eslint-disable-next-line no-unused-vars
const WeeklyScoreChart = ({ history, th }) => {
  const dayNames = ["月", "火", "水", "木", "金", "土", "日"];
  const last7 = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(); d.setDate(d.getDate() - (6 - i));
    const dateStr = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
    const entry = (history || []).find(h => h.date === dateStr);
    return { day: dayNames[d.getDay() === 0 ? 6 : d.getDay() - 1], score: entry?.score ?? 0 };
  });
  const maxScore = Math.max(...last7.map(d => d.score), 1);
  return (
    <div style={{ display: "flex", gap: 4, alignItems: "flex-end" }}>
      {last7.map((d, i) => (
        <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}>
          <div style={{ width: "100%", height: 40, display: "flex", alignItems: "flex-end", background: (th?.border || "#E5E7EB") + "50", borderRadius: "4px 4px 0 0", overflow: "hidden" }}>
            <div style={{ width: "100%", height: `${(d.score / maxScore) * 100}%`, background: th?.gradient || "linear-gradient(135deg,#34D399,#059669)", borderRadius: "4px 4px 0 0", transition: "height 1s ease" }} />
          </div>
          <span style={{ fontSize: 9, color: th?.subtext || "#6B7280" }}>{d.day}</span>
        </div>
      ))}
    </div>
  );
};

// ─── CONFETTI ────────────────────────────────────────────────────────────────
const ConfettiAnimation = ({ active, onDone }) => {
  useEffect(() => {
    if (!active) return;
    const t = setTimeout(onDone, 1500);
    return () => clearTimeout(t);
  }, [active, onDone]);
  if (!active) return null;
  const colors = ["#F59E0B", "#EF4444", "#10B981", "#3B82F6", "#8B5CF6", "#EC4899"];
  const pieces = Array.from({ length: 36 }, (_, i) => ({
    id: i, left: `${Math.random() * 100}%`,
    color: colors[i % colors.length],
    delay: `${Math.random() * 0.4}s`,
    duration: `${1.0 + Math.random() * 0.7}s`,
    size: `${8 + Math.random() * 10}px`,
  }));
  return (
    <div style={{ position: "absolute", inset: 0, pointerEvents: "none", overflow: "hidden", zIndex: 500 }}>
      {pieces.map(p => (
        <div key={p.id} style={{ position: "absolute", top: "-10px", left: p.left, width: p.size, height: p.size, background: p.color, borderRadius: 2, animation: `confettiFall ${p.duration} ${p.delay} ease-in forwards` }} />
      ))}
    </div>
  );
};

