// ─── AI SUGGESTION CARD ───────────────────────────────────────────────────────
// eslint-disable-next-line no-unused-vars
const AISuggestionCard = ({ suggestions, onAdd, onSkipOne, onSkipAll, th, cs }) => {
  const [idx, setIdx] = useState(0);
  useEffect(() => { setIdx(0); }, [suggestions]);
  if (!suggestions || suggestions.length === 0) return null;
  const current = suggestions[idx];
  if (!current) return null;
  const remaining = suggestions.length - idx;

  const handleSkip = () => {
    if (idx + 1 >= suggestions.length) { onSkipAll(); }
    else { setIdx(i => i + 1); if (onSkipOne) onSkipOne(current); }
  };

  return (
    <div style={{ background: th?.gradient || "linear-gradient(135deg,#34D399,#059669)", borderRadius: cs?.radius || 16, padding: "16px", marginTop: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <p style={{ fontSize: 13, fontWeight: 700, color: "#fff" }}>🤖 AIのおすすめTODO</p>
        <span style={{ fontSize: 11, color: "rgba(255,255,255,0.7)" }}>{idx + 1} / {suggestions.length}</span>
      </div>
      <div style={{ background: "rgba(255,255,255,0.18)", borderRadius: 12, padding: "14px 14px 12px" }}>
        <p style={{ fontSize: 14, fontWeight: 700, color: "#fff", marginBottom: 4, lineHeight: 1.4 }}>{current.title}</p>
        {current.reason && <p style={{ fontSize: 12, color: "rgba(255,255,255,0.8)", lineHeight: 1.5, marginBottom: 12 }}>{current.reason}</p>}
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={handleSkip} style={{ flex: 1, padding: "9px", borderRadius: 9, border: "1.5px solid rgba(255,255,255,0.5)", background: "transparent", color: "#fff", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
            {remaining > 1 ? "スキップ →" : "閉じる"}
          </button>
          <button onClick={() => { onAdd(current); if (idx + 1 < suggestions.length) setIdx(i => i + 1); else onSkipAll(); }} style={{ flex: 2, padding: "9px", borderRadius: 9, border: "none", background: "#fff", color: th?.primary || "#059669", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
            ✅ TODOに追加する
          </button>
        </div>
      </div>
      {remaining > 1 && (
        <div style={{ display: "flex", justifyContent: "center", gap: 5, marginTop: 10 }}>
          {suggestions.map((_, i) => (
            <div key={i} style={{ width: i === idx ? 16 : 6, height: 6, borderRadius: 99, background: i === idx ? "#fff" : "rgba(255,255,255,0.4)", transition: "all 0.2s" }} />
          ))}
        </div>
      )}
    </div>
  );
};

