// ─── HOME SCREEN ──────────────────────────────────────────────────────────────
const HomeScreen = ({ todos, folders, dopamineScore, setScreen, setEditTodo, onToggle, onDelete, onCreateFolder, th, cs }) => {
  const todayStr = today();
  const [activeTabId,  setActiveTabId]  = useState("all");
  const [activeSubId,  setActiveSubId]  = useState(null);
  const [swipedId,     setSwipedId]     = useState(null);
  const rowTouchStartX  = useRef(0);
  const tabSwipeStartX  = useRef(0);
  const tabSwipeStartY  = useRef(0);

  // 今日の進捗
  const totalCount   = todos.length;
  const doneCount    = todos.filter(t => isTodoDone(t, todayStr)).length;
  const progressPct  = totalCount === 0 ? 0 : Math.round((doneCount / totalCount) * 100);

  // 今日〜3日以内のおすすめTODO
  const threeDaysLater = (() => {
    const d = new Date(); d.setDate(d.getDate() + 3);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  })();
  const recommendedTodos = todos
    .filter(t => !isTodoDone(t, todayStr) && t.deadline && t.deadline <= threeDaysLater)
    .sort((a, b) => a.deadline.localeCompare(b.deadline))
    .slice(0, 5);

  // タブ
  const allTabs      = [{ id: "all", name: "すべて", emoji: "" }, ...folders];
  const activeTabIdx = allTabs.findIndex(t => t.id === activeTabId);
  const activeFolder = folders.find(f => f.id === activeTabId) || null;
  const activeSubfolders = activeFolder?.subfolders || [];

  const filtered = todos.filter(t => {
    if (activeTabId === "all") return true;
    if (t.folderId !== activeTabId) return false;
    if (activeSubId && t.subfolderId !== activeSubId) return false;
    return true;
  });
  const pendingTodos = sortByDeadlineTime(filtered.filter(t => !isTodoDone(t, todayStr)));
  const doneTodos    = filtered.filter(t => isTodoDone(t, todayStr));

  // 今週の完了数
  const weekDates = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(); d.setDate(d.getDate() - i);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  });
  const weeklyDoneCount = todos.reduce((sum, t) => {
    if (t.repeat && t.repeat !== "none") {
      return sum + (t.completedDates || []).filter(ds => weekDates.includes(ds)).length;
    }
    return sum + (t.done && weekDates.includes(t.doneDate) ? 1 : 0);
  }, 0);

  // 成長スコア
  const scoreColor   = dopamineScore >= 70 ? "#059669" : dopamineScore >= 40 ? "#F59E0B" : "#EF4444";
  const scoreMessage = dopamineScore >= 80 ? "絶好調！🔥" : dopamineScore >= 60 ? "好調✨" : dopamineScore >= 40 ? "まずまず💪" : "もう一踏ん張り🌱";
  const r            = 42;
  const circumference = 2 * Math.PI * r;
  const dashOffset    = circumference - (dopamineScore / 100) * circumference;

  // 期限ラベル
  const DeadlineChip = ({ deadline }) => {
    const diffDays = Math.floor((new Date(deadline + "T00:00:00") - new Date(todayStr + "T00:00:00")) / 86400000);
    const label = diffDays === 0 ? "今日" : diffDays === 1 ? "明日" : `${diffDays}日後`;
    const color = diffDays === 0 ? "#EF4444" : diffDays <= 1 ? "#F97316" : "#6B7280";
    const bg    = diffDays === 0 ? "#FEF2F2" : diffDays <= 1 ? "#FFF7ED" : "#F3F4F6";
    return <span style={{ fontSize: 11, color, fontWeight: 700, background: bg, padding: "2px 8px", borderRadius: 99, flexShrink: 0 }}>{label}</span>;
  };

  // 行スワイプ（削除）
  const handleRowTouchStart = (e, id) => {
    rowTouchStartX.current = e.touches[0].clientX;
    if (swipedId !== id) setSwipedId(null);
  };
  const handleRowTouchEnd = (e, id) => {
    const dx = rowTouchStartX.current - e.changedTouches[0].clientX;
    if (dx > 55) setSwipedId(id);
    else if (dx < -20) setSwipedId(null);
  };

  // タブスワイプ
  const handleTabSwipeStart = (e) => { tabSwipeStartX.current = e.touches[0].clientX; tabSwipeStartY.current = e.touches[0].clientY; };
  const handleTabSwipeEnd   = (e) => {
    const dx = tabSwipeStartX.current - e.changedTouches[0].clientX;
    const dy = tabSwipeStartY.current - e.changedTouches[0].clientY;
    if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.5) {
      const newIdx = dx > 0 ? Math.min(activeTabIdx + 1, allTabs.length - 1) : Math.max(activeTabIdx - 1, 0);
      if (newIdx !== activeTabIdx) { setActiveTabId(allTabs[newIdx].id); setActiveSubId(null); }
    }
  };

  const TodoRow = ({ todo }) => {
    const done   = isTodoDone(todo, todayStr);
    const swiped = swipedId === todo.id;
    return (
      <div style={{ position: "relative", overflow: "hidden" }}>
        <div style={{ position: "absolute", right: 0, top: 0, bottom: 0, width: 80, background: "#EF4444", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
          <button onClick={() => { onDelete(todo.id); setSwipedId(null); }} style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
            <span style={{ fontSize: 20 }}>🗑</span>
            <span style={{ fontSize: 11, fontWeight: 700 }}>削除</span>
          </button>
        </div>
        <div
          onTouchStart={e => handleRowTouchStart(e, todo.id)}
          onTouchEnd={e => handleRowTouchEnd(e, todo.id)}
          onClick={() => { if (swiped) { setSwipedId(null); return; } setEditTodo(todo); setScreen("detail"); }}
          style={{ display: "flex", alignItems: "center", gap: 14, padding: "15px 18px", background: "#fff", borderBottom: "1px solid #F5F5F5", transform: swiped ? "translateX(-80px)" : "translateX(0)", transition: "transform 0.22s ease", opacity: done ? 0.38 : 1, cursor: "pointer" }}
        >
          <button
            onClick={e => { e.stopPropagation(); onToggle(todo.id); }}
            style={{ width: 24, height: 24, borderRadius: 99, border: `2px solid ${done ? "#059669" : "#D1D5DB"}`, background: done ? "#059669" : "transparent", cursor: "pointer", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontSize: 12, transition: "background 0.18s, border-color 0.18s" }}
          >
            {done && "✓"}
          </button>
          <div style={{ flex: 1, minWidth: 0 }}>
            <p style={{ fontSize: 16, fontWeight: 500, color: "#111827", textDecoration: done ? "line-through" : "none", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", lineHeight: 1.4 }}>{todo.title}</p>
            {todo.deadline && <p style={{ fontSize: 12, color: "#9CA3AF", marginTop: 2 }}>{new Date(todo.deadline + "T00:00:00").toLocaleDateString("ja-JP", { month: "numeric", day: "numeric" })}{todo.deadlineTime ? " " + todo.deadlineTime : ""}</p>}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden", background: "#F4F4F4" }}>
      <div style={{ flex: 1, overflowY: "auto" }} onClick={() => swipedId && setSwipedId(null)}>

        {/* ① ヘッダー */}
        <div style={{ padding: "52px 20px 14px", display: "flex", justifyContent: "space-between", alignItems: "center", background: "#fff" }}>
          <span style={{ fontSize: 22, fontWeight: 800, color: "#111827", letterSpacing: -0.5 }}>TODO LIFE</span>
          <button onClick={() => setScreen("settings")} style={{ width: 36, height: 36, borderRadius: 99, background: "#F3F4F6", border: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", fontSize: 17 }}>⚙️</button>
        </div>

        {/* ② 成長スコア ＋ ③ 今日の進捗 */}
        <div style={{ margin: "10px 14px 0", background: "#fff", borderRadius: 20, padding: "18px 20px", boxShadow: "0 1px 8px rgba(0,0,0,0.07)", display: "flex", gap: 18, alignItems: "center" }}>
          {/* 円グラフ */}
          <div style={{ flexShrink: 0, textAlign: "center" }}>
            <svg width={106} height={106} viewBox="0 0 106 106">
              <circle cx={53} cy={53} r={r} fill="none" stroke="#F0F0F0" strokeWidth={9} />
              <circle cx={53} cy={53} r={r} fill="none" stroke={scoreColor} strokeWidth={9}
                strokeDasharray={circumference} strokeDashoffset={dashOffset}
                strokeLinecap="round" transform="rotate(-90 53 53)"
                style={{ transition: "stroke-dashoffset 1s ease" }}
              />
              <text x={53} y={49} textAnchor="middle" fontSize={22} fontWeight="800" fill="#111827">{dopamineScore}</text>
              <text x={53} y={65} textAnchor="middle" fontSize={11} fill="#9CA3AF">点</text>
            </svg>
            <p style={{ fontSize: 12, color: scoreColor, fontWeight: 700, marginTop: 2 }}>{scoreMessage}</p>
          </div>

          {/* 右側：ラベル + 進捗 */}
          <div style={{ flex: 1 }}>
            <p style={{ fontSize: 14, fontWeight: 700, color: "#111827", marginBottom: 2 }}>今日の成長スコア</p>
            <p style={{ fontSize: 12, color: "#9CA3AF", marginBottom: 16, lineHeight: 1.5 }}>TODOをこなすと<br />スコアが上がる！</p>
            <p style={{ fontSize: 12, fontWeight: 700, color: "#374151", marginBottom: 7 }}>今日の進捗</p>
            <div style={{ height: 7, borderRadius: 99, background: "#F0F0F0", overflow: "hidden", marginBottom: 6 }}>
              <div style={{ height: "100%", borderRadius: 99, background: "linear-gradient(90deg,#34D399,#059669)", width: `${progressPct}%`, transition: "width 0.8s ease" }} />
            </div>
            <p style={{ fontSize: 12, color: "#9CA3AF" }}>
              <span style={{ color: "#059669", fontWeight: 700, fontSize: 15 }}>{doneCount}</span>/{totalCount} 完了
            </p>
          </div>
        </div>

        {/* ③-b 今週の進捗バー */}
        <button onClick={() => setScreen("growthGraph")} style={{ display: "flex", alignItems: "center", gap: 10, margin: "8px 14px 0", background: "#fff", borderRadius: 16, padding: "12px 16px", boxShadow: "0 1px 8px rgba(0,0,0,0.07)", width: "calc(100% - 28px)", border: "none", cursor: "pointer", textAlign: "left" }}>
          <span style={{ fontSize: 18, flexShrink: 0 }}>📊</span>
          <div style={{ flex: 1 }}>
            <p style={{ fontSize: 12, fontWeight: 700, color: "#374151", marginBottom: 4 }}>今週 <span style={{ color: "#059669" }}>{weeklyDoneCount}個</span>完了</p>
            <div style={{ height: 5, borderRadius: 99, background: "#F0F0F0", overflow: "hidden" }}>
              <div style={{ height: "100%", borderRadius: 99, background: "linear-gradient(90deg,#34D399,#059669)", width: `${Math.min(100, weeklyDoneCount * 10)}%`, transition: "width 0.8s ease" }} />
            </div>
          </div>
          <span style={{ fontSize: 16, color: "#ADADAD", flexShrink: 0 }}>›</span>
        </button>

        {/* ④ 今日のおすすめTODO */}
        {recommendedTodos.length > 0 && (
          <div style={{ margin: "10px 14px 0", background: "#fff", borderRadius: 20, overflow: "hidden", boxShadow: "0 1px 8px rgba(0,0,0,0.07)" }}>
            <div style={{ padding: "16px 18px 10px", display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 15 }}>⚡</span>
              <p style={{ fontSize: 14, fontWeight: 700, color: "#111827" }}>今日やること</p>
              <span style={{ fontSize: 12, color: "#ADADAD", marginLeft: "auto" }}>{recommendedTodos.length}件</span>
            </div>
            {recommendedTodos.map((todo, i) => (
              <div key={todo.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 18px", borderTop: "1px solid #F5F5F5" }}>
                <button
                  onClick={() => onToggle(todo.id)}
                  style={{ width: 22, height: 22, borderRadius: 99, border: "2px solid #D1D5DB", background: "transparent", cursor: "pointer", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, color: "#fff", transition: "background 0.18s" }}
                />
                <p style={{ flex: 1, fontSize: 15, fontWeight: 500, color: "#111827", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{todo.title}</p>
                <DeadlineChip deadline={todo.deadline} />
              </div>
            ))}
            <div style={{ height: 6 }} />
          </div>
        )}

        {/* ⑤ タブ ＋ ⑥ TODOリスト */}
        <div style={{ margin: "10px 14px 0", background: "#fff", borderRadius: 20, overflow: "hidden", boxShadow: "0 1px 8px rgba(0,0,0,0.07)" }}
          onTouchStart={handleTabSwipeStart} onTouchEnd={handleTabSwipeEnd}>

          {/* タブバー */}
          <div style={{ display: "flex", overflowX: "auto", padding: "0 6px" }}>
            {allTabs.map(tab => {
              const isActive    = activeTabId === tab.id;
              const accentColor = folders.find(f => f.id === tab.id)?.color || "#059669";
              return (
                <button key={tab.id} onClick={() => { setActiveTabId(tab.id); setActiveSubId(null); }}
                  style={{ padding: "13px 13px", background: "none", border: "none", cursor: "pointer", borderBottom: `2.5px solid ${isActive ? accentColor : "transparent"}`, color: isActive ? accentColor : "#ADADAD", fontSize: 14, fontWeight: isActive ? 700 : 400, whiteSpace: "nowrap", flexShrink: 0, transition: "color 0.15s, border-color 0.15s", display: "flex", alignItems: "center", gap: 4 }}>
                  {tab.emoji && <span>{tab.emoji}</span>}
                  <span>{tab.name || "すべて"}</span>
                </button>
              );
            })}
            <button onClick={onCreateFolder} style={{ padding: "13px 13px", background: "none", border: "none", cursor: "pointer", color: "#ADADAD", fontSize: 20, borderBottom: "2.5px solid transparent", flexShrink: 0 }}>＋</button>
          </div>
          <div style={{ height: 1, background: "#F5F5F5" }} />

          {activeFolder && activeSubfolders.length > 0 && (
            <div style={{ display: "flex", gap: 8, overflowX: "auto", padding: "10px 14px" }}>
              <button onClick={() => setActiveSubId(null)} style={{ padding: "4px 12px", borderRadius: 20, border: "none", background: !activeSubId ? "#059669" : "#F3F4F6", color: !activeSubId ? "#fff" : "#6B7280", fontSize: 12, fontWeight: 600, cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0 }}>すべて</button>
              {activeSubfolders.map(sf => (
                <button key={sf.id} onClick={() => setActiveSubId(sf.id === activeSubId ? null : sf.id)} style={{ padding: "4px 12px", borderRadius: 20, border: "none", background: activeSubId === sf.id ? (activeFolder.color || "#059669") : "#F3F4F6", color: activeSubId === sf.id ? "#fff" : "#6B7280", fontSize: 12, fontWeight: 600, cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0 }}>{sf.emoji} {sf.name}</button>
              ))}
            </div>
          )}

          {/* TODOリスト（完了済みは非表示） */}
          {pendingTodos.length === 0 ? (
            <div style={{ textAlign: "center", padding: "36px 24px" }}>
              <div style={{ fontSize: 40, marginBottom: 10 }}>✅</div>
              <p style={{ fontSize: 16, fontWeight: 700, color: "#111827", marginBottom: 6 }}>
                {doneTodos.length > 0 ? "今日のタスクをすべて完了！" : "このフォルダは空！"}
              </p>
              <p style={{ fontSize: 13, color: "#ADADAD" }}>
                {doneTodos.length > 0 ? `${doneTodos.length}件完了 🎉` : "＋ ボタンでTODOを追加しよう"}
              </p>
            </div>
          ) : (
            pendingTodos.map(todo => <TodoRow key={todo.id} todo={todo} />)
          )}
        </div>

        <div style={{ height: 48 }} />
      </div>
    </div>
  );
};


// ─── ADD/EDIT SCREEN ──────────────────────────────────────────────────────────
const AddScreen = ({ setScreen, editTodo, onSave, onAddExtra, categories, openCatModal, folders, th, cs }) => {
  const isEdit = !!editTodo;
  const [title,        setTitle]        = useState(editTodo?.title        || "");
  const [deadline,     setDeadline]     = useState(editTodo?.deadline     || "");
  const [deadlineTime, setDeadlineTime] = useState(editTodo?.deadlineTime || "");
  const [category,     setCategory]     = useState(editTodo?.category     || (categories[0]?.id ?? "")); // eslint-disable-line no-unused-vars
  const [memo,         setMemo]         = useState(editTodo?.memo         || "");
  const [repeat,       setRepeat]       = useState(editTodo?.repeat       || "none");
  const [repeatTime,   setRepeatTime]   = useState(editTodo?.repeatTime   || "");
  const [subtasks,     setSubtasks]     = useState(editTodo?.subtasks     || []);
  const [folderId,     setFolderId]     = useState(editTodo?.folderId     || "");
  const [subfolderId,  setSubfolderId]  = useState(editTodo?.subfolderId  || "");

  // カメラスキャン状態: idle | preview | scanning | result
  const [scanPhase,    setScanPhase]    = useState("idle");
  const [scanProgress, setScanProgress] = useState(0);
  const [previewUrl,   setPreviewUrl]   = useState(null);
  const [previewFile,  setPreviewFile]  = useState(null);
  const [dragStart,    setDragStart]    = useState(null); // {x,y} in preview coords
  const [dragEnd,      setDragEnd]      = useState(null);
  const [scanLines,    setScanLines]    = useState([]);   // [{text, checked}]

  const cameraRef  = useRef(null);
  const photoRef   = useRef(null);
  const imgRef     = useRef(null);
  const previewRef = useRef(null);
  const isDragging = useRef(false);

  const save = () => {
    if (!title.trim()) return;
    onSave({ title, deadline, deadlineTime: deadline ? deadlineTime : "", category, memo, repeat, repeatTime: repeat !== "none" ? repeatTime : "", subtasks, folderId: folderId || null, subfolderId: (folderId && subfolderId) ? subfolderId : null }, isEdit ? editTodo.id : null);
    setScreen("home");
  };

  // passive:false が必要なタッチ操作をuseEffectで登録
  useEffect(() => {
    const el = previewRef.current;
    if (!el || scanPhase !== "preview") return;
    const getPos = (cx, cy) => {
      const r = el.getBoundingClientRect();
      return { x: Math.max(0, Math.min(cx - r.left, r.width)), y: Math.max(0, Math.min(cy - r.top, r.height)) };
    };
    const onStart = (e) => { e.preventDefault(); const t = e.touches[0]; setDragStart(getPos(t.clientX, t.clientY)); setDragEnd(null); isDragging.current = true; };
    const onMove  = (e) => { e.preventDefault(); if (!isDragging.current) return; const t = e.touches[0]; setDragEnd(getPos(t.clientX, t.clientY)); };
    const onEnd   = (e) => { e.preventDefault(); isDragging.current = false; };
    el.addEventListener("touchstart", onStart, { passive: false });
    el.addEventListener("touchmove",  onMove,  { passive: false });
    el.addEventListener("touchend",   onEnd,   { passive: false });
    return () => {
      el.removeEventListener("touchstart", onStart);
      el.removeEventListener("touchmove",  onMove);
      el.removeEventListener("touchend",   onEnd);
    };
  }, [scanPhase]);

  // 画像をリサイズ・JPEG圧縮してbase64を返す
  const compressImage = (file, maxPx = 1024, quality = 0.7) =>
    new Promise((resolve, reject) => {
      const img = new Image();
      const url = URL.createObjectURL(file);
      img.onload = () => {
        URL.revokeObjectURL(url);
        const scale = Math.min(1, maxPx / Math.max(img.width, img.height));
        const w = Math.round(img.width * scale), h = Math.round(img.height * scale);
        const c = document.createElement("canvas");
        c.width = w; c.height = h;
        c.getContext("2d").drawImage(img, 0, 0, w, h);
        resolve(c.toDataURL("image/jpeg", quality).split(",")[1]);
      };
      img.onerror = reject;
      img.src = url;
    });

  // Google Cloud Vision API呼び出し（共通）
  const callVisionAPI = async (base64) => {
    const apiKey = process.env.REACT_APP_GOOGLE_VISION_API_KEY;
    if (!apiKey) throw new Error("APIキーが未設定です");
    const res = await fetch(`https://vision.googleapis.com/v1/images:annotate?key=${apiKey}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ requests: [{ image: { content: base64 }, features: [{ type: "DOCUMENT_TEXT_DETECTION" }], imageContext: { languageHints: ["ja", "en"] } }] }),
    });
    if (!res.ok) {
      const err = await res.json(); const code = res.status;
      if (code === 400) throw new Error("画像形式が正しくありません");
      if (code === 403) throw new Error("APIキーが無効またはVision APIが未有効化です");
      if (code === 429) throw new Error("使用制限に達しました。しばらく後に再試行してください");
      throw new Error(err.error?.message || `APIエラー (${code})`);
    }
    const data = await res.json();
    return data.responses?.[0]?.fullTextAnnotation?.text || data.responses?.[0]?.textAnnotations?.[0]?.description || "";
  };

  const textToLines = (text) =>
    text.trim().split("\n").map(l => l.trim()).filter(Boolean).map(t => ({ text: t, checked: true }));

  const closeScan = () => {
    setScanPhase("idle");
    if (previewUrl) { URL.revokeObjectURL(previewUrl); setPreviewUrl(null); }
    setPreviewFile(null); setDragStart(null); setDragEnd(null);
  };

  // ファイル選択（カメラ・写真ライブラリ共通）
  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files || []);
    e.target.value = "";
    if (files.length === 0) return;
    if (files.length > 1) { handleMultipleFiles(files); return; }
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(URL.createObjectURL(files[0]));
    setPreviewFile(files[0]);
    setDragStart(null); setDragEnd(null);
    setScanPhase("preview");
  };

  // 全体スキャン（プレビューから）
  const handleScanFull = async () => {
    setScanPhase("scanning"); setScanProgress(10);
    try {
      const base64 = await compressImage(previewFile); setScanProgress(50);
      const text = await callVisionAPI(base64); setScanProgress(90);
      if (!text.trim()) throw new Error("文字が検出できませんでした。明るい場所で撮影してください");
      setScanLines(textToLines(text)); setScanPhase("result"); setScanProgress(100);
    } catch (err) { setScanPhase("preview"); alert(`スキャン失敗: ${err.message}`); }
  };

  // 範囲選択スキャン
  const handleScanSelection = async () => {
    if (!dragStart || !dragEnd || !imgRef.current) return handleScanFull();
    const img = imgRef.current;
    const x1 = Math.min(dragStart.x, dragEnd.x), y1 = Math.min(dragStart.y, dragEnd.y);
    const w  = Math.abs(dragEnd.x - dragStart.x), h  = Math.abs(dragEnd.y - dragStart.y);
    if (w < 10 || h < 10) return handleScanFull();
    setScanPhase("scanning"); setScanProgress(10);
    try {
      const sx = img.naturalWidth / img.offsetWidth, sy = img.naturalHeight / img.offsetHeight;
      const c1 = document.createElement("canvas");
      c1.width = Math.round(w * sx); c1.height = Math.round(h * sy);
      c1.getContext("2d").drawImage(img, Math.round(x1*sx), Math.round(y1*sy), c1.width, c1.height, 0, 0, c1.width, c1.height);
      const sc = Math.min(1, 1024 / Math.max(c1.width, c1.height));
      const c2 = document.createElement("canvas");
      c2.width = Math.round(c1.width * sc); c2.height = Math.round(c1.height * sc);
      c2.getContext("2d").drawImage(c1, 0, 0, c2.width, c2.height);
      const base64 = c2.toDataURL("image/jpeg", 0.8).split(",")[1];
      setScanProgress(50);
      const text = await callVisionAPI(base64); setScanProgress(90);
      if (!text.trim()) throw new Error("選択範囲に文字が検出できませんでした");
      setScanLines(textToLines(text)); setScanPhase("result"); setScanProgress(100);
    } catch (err) { setScanPhase("preview"); alert(`スキャン失敗: ${err.message}`); }
  };

  // 複数ファイル一括スキャン
  const handleMultipleFiles = async (files) => {
    setScanPhase("scanning"); setScanProgress(0);
    try {
      const allLines = [];
      for (let i = 0; i < files.length; i++) {
        setScanProgress(Math.round((i / files.length) * 80));
        const base64 = await compressImage(files[i]);
        const text   = await callVisionAPI(base64);
        text.trim().split("\n").map(l => l.trim()).filter(Boolean).forEach(t => allLines.push(t));
      }
      if (allLines.length === 0) throw new Error("文字が検出できませんでした");
      setScanLines(allLines.map(t => ({ text: t, checked: true }))); setScanPhase("result"); setScanProgress(100);
    } catch (err) { setScanPhase("idle"); alert(`スキャン失敗: ${err.message}`); }
  };

  // 選択行の最初をタイトルに適用
  const applyFirstLine = () => {
    const line = scanLines.find(l => l.checked);
    if (line) setTitle(line.text);
    closeScan();
  };

  // 選択行を全てTODOとして追加
  const addAllSelected = async () => {
    const selected = scanLines.filter(l => l.checked && l.text.trim());
    if (selected.length === 0) return;
    for (const line of selected) await onAddExtra(line.text);
    closeScan();
    setScreen("list");
  };

  const inputStyle = {
    width: "100%", padding: "12px 14px", borderRadius: 12, border: `1.5px solid ${th?.border || "#E5E7EB"}`,
    fontSize: 14, color: th?.text || "#111827", background: th?.bg || "#FAFAFA", outline: "none",
    boxSizing: "border-box", fontFamily: "inherit",
  };

  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 40 }}>
      <div style={{ display: "flex", alignItems: "center", padding: "20px 20px 16px", gap: 12 }}>
        <button onClick={() => setScreen("home")} style={{ fontSize: 22, color: th?.subtext || "#6B7280", background: "none", border: "none", cursor: "pointer", lineHeight: 1, padding: "0 4px" }}>‹</button>
        <h2 style={{ fontSize: 17, fontWeight: 700, color: th?.text || "#111827" }}>{isEdit ? "TODO を編集" : "新しい TODO"}</h2>
      </div>

      <div style={{ padding: "0 20px", display: "flex", flexDirection: "column", gap: 16 }}>

        {/* ── プレビュー & 範囲選択 ── */}
        {scanPhase === "preview" && (() => {
          const hasSel = dragStart && dragEnd && Math.abs(dragEnd.x - dragStart.x) > 10 && Math.abs(dragEnd.y - dragStart.y) > 10;
          const x1 = hasSel ? Math.min(dragStart.x, dragEnd.x) : 0;
          const y1 = hasSel ? Math.min(dragStart.y, dragEnd.y) : 0;
          const x2 = hasSel ? Math.max(dragStart.x, dragEnd.x) : 0;
          const y2 = hasSel ? Math.max(dragStart.y, dragEnd.y) : 0;
          return (
            <div style={{ borderRadius: 12, border: "1.5px solid #E5E7EB", overflow: "hidden", background: "#000" }}>
              <div
                ref={previewRef}
                style={{ position: "relative", userSelect: "none", cursor: "crosshair" }}
                onMouseDown={e => { const r = e.currentTarget.getBoundingClientRect(); setDragStart({ x: e.clientX - r.left, y: e.clientY - r.top }); setDragEnd(null); isDragging.current = true; }}
                onMouseMove={e => { if (!isDragging.current) return; const r = e.currentTarget.getBoundingClientRect(); setDragEnd({ x: Math.max(0, Math.min(e.clientX - r.left, r.width)), y: Math.max(0, Math.min(e.clientY - r.top, r.height)) }); }}
                onMouseUp={() => { isDragging.current = false; }}
              >
                <img ref={imgRef} src={previewUrl} alt="" style={{ width: "100%", display: "block" }} />
                {hasSel && (
                  <>
                    <div style={{ position: "absolute", left: 0, top: 0, right: 0, height: y1, background: "rgba(0,0,0,0.5)", pointerEvents: "none" }} />
                    <div style={{ position: "absolute", left: 0, top: y2, right: 0, bottom: 0, background: "rgba(0,0,0,0.5)", pointerEvents: "none" }} />
                    <div style={{ position: "absolute", left: 0, top: y1, width: x1, height: y2 - y1, background: "rgba(0,0,0,0.5)", pointerEvents: "none" }} />
                    <div style={{ position: "absolute", left: x2, top: y1, right: 0, height: y2 - y1, background: "rgba(0,0,0,0.5)", pointerEvents: "none" }} />
                    <div style={{ position: "absolute", left: x1, top: y1, width: x2 - x1, height: y2 - y1, border: "2px solid #34D399", boxSizing: "border-box", pointerEvents: "none" }}>
                      {[{ left: -4, top: -4 }, { right: -4, top: -4 }, { left: -4, bottom: -4 }, { right: -4, bottom: -4 }].map((s, i) => (
                        <div key={i} style={{ position: "absolute", width: 8, height: 8, background: "#059669", borderRadius: 2, ...s }} />
                      ))}
                    </div>
                  </>
                )}
              </div>
              <div style={{ padding: "12px 14px", background: "#fff", display: "flex", flexDirection: "column", gap: 8 }}>
                <p style={{ fontSize: 12, color: "#6B7280" }}>
                  {hasSel ? "✅ 範囲を選択しました。スキャンしてください" : "📌 ドラッグして読み取りたい範囲を選択（省略可）"}
                </p>
                <div style={{ display: "flex", gap: 8 }}>
                  <button onClick={hasSel ? handleScanSelection : handleScanFull} style={{ flex: 1, padding: "10px", borderRadius: 10, border: "none", background: "linear-gradient(135deg,#34D399,#059669)", color: "#fff", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
                    {hasSel ? "選択範囲をスキャン" : "全体をスキャン"}
                  </button>
                  <button onClick={closeScan} style={{ padding: "10px 14px", borderRadius: 10, border: "1.5px solid #E5E7EB", background: "#fff", color: "#6B7280", fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>キャンセル</button>
                </div>
              </div>
            </div>
          );
        })()}

        {/* ── スキャン中 ── */}
        {scanPhase === "scanning" && (
          <div style={{ padding: "14px", background: "#F9FAFB", borderRadius: 12, border: "1.5px solid #E5E7EB" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
              <div style={{ width: 18, height: 18, borderRadius: 99, border: "2.5px solid #E5E7EB", borderTopColor: "#059669", animation: "spin 0.7s linear infinite", flexShrink: 0 }} />
              <p style={{ fontSize: 13, color: "#374151", fontWeight: 600 }}>
                {scanProgress < 40 ? "📸 画像を圧縮中..." : scanProgress < 80 ? "🌐 APIに送信中..." : "🔍 テキストを認識中..."}
              </p>
            </div>
            <div style={{ height: 6, background: "#E5E7EB", borderRadius: 99, overflow: "hidden" }}>
              <div style={{ width: `${scanProgress}%`, height: "100%", background: "linear-gradient(90deg,#34D399,#059669)", transition: "width 0.4s ease" }} />
            </div>
            <p style={{ fontSize: 11, color: "#9CA3AF", marginTop: 6 }}>{scanProgress}% 完了</p>
          </div>
        )}

        {/* ── スキャン結果（行ごとにチェックボックス）── */}
        {scanPhase === "result" && (
          <div style={{ padding: "14px", background: "#F9FAFB", borderRadius: 12, border: "1.5px solid #E5E7EB" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
              <p style={{ fontSize: 12, fontWeight: 700, color: "#374151" }}>
                📋 {scanLines.filter(l => l.checked).length}/{scanLines.length}行を選択中
              </p>
              <div style={{ display: "flex", gap: 10 }}>
                <button onClick={() => setScanLines(ls => ls.map(l => ({ ...l, checked: true  })))} style={{ fontSize: 11, color: "#059669", fontWeight: 700, background: "none", border: "none", cursor: "pointer", fontFamily: "inherit" }}>全選択</button>
                <button onClick={() => setScanLines(ls => ls.map(l => ({ ...l, checked: false })))} style={{ fontSize: 11, color: "#9CA3AF", background: "none", border: "none", cursor: "pointer", fontFamily: "inherit" }}>全解除</button>
              </div>
            </div>
            <div style={{ maxHeight: 200, overflowY: "auto", display: "flex", flexDirection: "column", gap: 4 }}>
              {scanLines.map((line, i) => (
                <label key={i} style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "8px 10px", background: line.checked ? "#ECFDF5" : "#fff", borderRadius: 8, border: `1px solid ${line.checked ? "#A7F3D0" : "#E5E7EB"}`, cursor: "pointer" }}>
                  <input type="checkbox" checked={line.checked} onChange={ev => setScanLines(ls => ls.map((l, j) => j === i ? { ...l, checked: ev.target.checked } : l))} style={{ marginTop: 2, accentColor: "#059669", flexShrink: 0, width: 15, height: 15 }} />
                  <span style={{ fontSize: 13, color: "#111827", lineHeight: 1.5, wordBreak: "break-all" }}>{line.text}</span>
                </label>
              ))}
            </div>
            <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
              <button onClick={applyFirstLine} style={{ flex: 1, padding: "10px", borderRadius: 10, border: "none", background: "#059669", color: "#fff", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>タイトルに適用</button>
              <button onClick={addAllSelected} style={{ flex: 1, padding: "10px", borderRadius: 10, border: "1.5px solid #059669", background: "#fff", color: "#059669", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>まとめて追加</button>
            </div>
            <button onClick={closeScan} style={{ width: "100%", marginTop: 8, padding: "8px", borderRadius: 10, border: "1.5px solid #E5E7EB", background: "#fff", color: "#9CA3AF", fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>閉じる</button>
          </div>
        )}

        {/* やること */}
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
            <label style={{ fontSize: 13, fontWeight: 600, color: "#374151" }}>やること *</label>
            <div style={{ display: "flex", gap: 6 }}>
              <VoiceButton onResult={setTitle} />
              <button onClick={() => cameraRef.current?.click()} type="button" style={{ display: "inline-flex", alignItems: "center", gap: 3, padding: "3px 9px", borderRadius: 99, border: "none", cursor: "pointer", background: "#FFF7ED", color: "#C2410C", fontSize: 11, fontWeight: 600, fontFamily: "inherit" }}>📷 撮影</button>
              <button onClick={() => photoRef.current?.click()} type="button" style={{ display: "inline-flex", alignItems: "center", gap: 3, padding: "3px 9px", borderRadius: 99, border: "none", cursor: "pointer", background: "#F0FDF4", color: "#166534", fontSize: 11, fontWeight: 600, fontFamily: "inherit" }}>🖼️ 選択</button>
              <input ref={cameraRef} type="file" accept="image/*" capture="environment" onChange={handleFileSelect} style={{ display: "none" }} />
              <input ref={photoRef} type="file" accept="image/*" multiple onChange={handleFileSelect} style={{ display: "none" }} />
            </div>
          </div>
          <input value={title} onChange={e => setTitle(e.target.value)} placeholder="例）本を読む" style={inputStyle} />
        </div>

        {/* サブタスク */}
        <div>
          <label style={{ fontSize: 13, fontWeight: 600, color: "#374151", display: "block", marginBottom: 8 }}>
            サブタスク <span style={{ fontWeight: 400, color: "#9CA3AF" }}>（任意）</span>
          </label>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {subtasks.map((st, i) => (
              <div key={st.id} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                <input
                  value={st.text}
                  onChange={e => setSubtasks(prev => prev.map((s, j) => j === i ? { ...s, text: e.target.value } : s))}
                  placeholder={`サブタスク ${i + 1}`}
                  style={inputStyle}
                />
                <button type="button" onClick={() => setSubtasks(prev => prev.filter((_, j) => j !== i))} style={{ width: 34, height: 34, borderRadius: 8, border: "1.5px solid #FCA5A5", background: "#FEF2F2", color: "#EF4444", fontSize: 18, cursor: "pointer", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>×</button>
              </div>
            ))}
            <button type="button" onClick={() => setSubtasks(prev => [...prev, { id: `st_${Date.now()}`, text: "", done: false }])} style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "11px 14px", borderRadius: 10, border: "1.5px dashed #A7F3D0", background: "#F0FDF4", color: "#059669", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
              ＋ サブタスクを追加
            </button>
          </div>
        </div>

        {/* 繰り返し */}
        <div>
          <label style={{ fontSize: 13, fontWeight: 600, color: "#374151", display: "block", marginBottom: 8 }}>繰り返し</label>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            {REPEAT_OPTIONS.map(opt => (
              <button key={opt.value} onClick={() => setRepeat(opt.value)} style={{ padding: "7px 14px", borderRadius: 20, border: `2px solid ${repeat === opt.value ? "#7C3AED" : "#E5E7EB"}`, background: repeat === opt.value ? "#F5F3FF" : "#fff", color: repeat === opt.value ? "#7C3AED" : "#6B7280", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", transition: "all 0.15s" }}>
                {repeat === opt.value && opt.value !== "none" ? `🔁 ${opt.label}` : opt.label}
              </button>
            ))}
          </div>
          {repeat !== "none" && (
            <div style={{ marginTop: 14 }}>
              <p style={{ fontSize: 12, color: "#6B7280", fontWeight: 600, marginBottom: 10 }}>⏰ 通知時刻 <span style={{ fontWeight: 400, color: "#9CA3AF" }}>（任意）</span></p>
              <DrumPicker value={repeatTime || "08:00"} onChange={setRepeatTime} th={th} />
              {repeatTime && (
                <div style={{ marginTop: 8, padding: "8px 12px", background: "#F5F3FF", borderRadius: 10, display: "inline-flex", alignItems: "center", gap: 6 }}>
                  <span style={{ fontSize: 13, color: "#7C3AED", fontWeight: 600 }}>🔁 {REPEAT_LABELS[repeat]} {repeatTime} に通知</span>
                </div>
              )}
            </div>
          )}
        </div>

        {/* いつまでに */}
        <div>
          <label style={{ fontSize: 13, fontWeight: 600, color: "#374151", display: "block", marginBottom: 6 }}>いつまでに？ <span style={{ fontWeight: 400, color: "#9CA3AF" }}>（任意）</span></label>

          {/* 日付入力 */}
          <input
            type="date"
            value={deadline}
            onChange={e => { setDeadline(e.target.value); if (!e.target.value) setDeadlineTime(""); }}
            style={inputStyle}
          />

          {/* 時間ボタン（日付設定後に表示） */}
          {deadline && (
            <div style={{ marginTop: 10 }}>
              <p style={{ fontSize: 12, color: "#6B7280", fontWeight: 600, marginBottom: 8 }}>⏰ 時間 <span style={{ fontWeight: 400, color: "#9CA3AF" }}>（任意）</span></p>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {/* 終日ボタン */}
                <button type="button" onClick={() => setDeadlineTime("")} style={{
                  padding: "8px 14px", borderRadius: 20, fontSize: 13, fontWeight: 600,
                  cursor: "pointer", fontFamily: "inherit", border: "2px solid",
                  borderColor: !deadlineTime ? "#059669" : "#E5E7EB",
                  background: !deadlineTime ? "#ECFDF5" : "#fff",
                  color: !deadlineTime ? "#059669" : "#6B7280",
                }}>終日</button>
                {/* 時間ボタン群 */}
                {HOUR_OPTIONS.map(h => (
                  <button key={h} type="button" onClick={() => setDeadlineTime(h)} style={{
                    padding: "8px 10px", borderRadius: 20, fontSize: 12, fontWeight: 600,
                    cursor: "pointer", fontFamily: "inherit", border: "2px solid",
                    borderColor: deadlineTime === h ? "#F97316" : "#E5E7EB",
                    background: deadlineTime === h ? "#FFF7ED" : "#fff",
                    color: deadlineTime === h ? "#F97316" : "#6B7280",
                    minWidth: 56,
                  }}>{h}</button>
                ))}
              </div>
            </div>
          )}

          {/* 確認テキスト */}
          {deadline && (
            <div style={{ marginTop: 10, padding: "10px 14px", background: deadlineTime ? "#FFF7ED" : "#F0FDF4", borderRadius: 10 }}>
              <p style={{ fontSize: 13, color: deadlineTime ? "#F97316" : "#059669", fontWeight: 600 }}>
                {deadlineTime ? `⏰ ${new Date(deadline + "T00:00:00").toLocaleDateString("ja-JP", { month: "long", day: "numeric" })} ${deadlineTime}まで` : `📅 ${new Date(deadline + "T00:00:00").toLocaleDateString("ja-JP", { month: "long", day: "numeric" })}まで（終日）`}
              </p>
            </div>
          )}
        </div>

        {/* フォルダ */}
        {folders && folders.length > 0 && (
          <div>
            <label style={{ fontSize: 13, fontWeight: 600, color: "#374151", display: "block", marginBottom: 8 }}>フォルダ <span style={{ fontWeight: 400, color: "#9CA3AF" }}>（任意）</span></label>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              <button onClick={() => { setFolderId(""); setSubfolderId(""); }} style={{ padding: "7px 14px", borderRadius: 20, border: `2px solid ${!folderId ? "#059669" : "#E5E7EB"}`, background: !folderId ? "#ECFDF5" : "#fff", color: !folderId ? "#059669" : "#6B7280", fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
                なし
              </button>
              {folders.map(f => {
                const fbg = FOLDER_COLORS.find(c => c.color === f.color)?.bg || "#ECFDF5";
                return (
                  <button key={f.id} onClick={() => { setFolderId(f.id); setSubfolderId(""); }} style={{ padding: "7px 14px", borderRadius: 20, border: `2px solid ${folderId === f.id ? f.color : "#E5E7EB"}`, background: folderId === f.id ? fbg : "#fff", color: folderId === f.id ? f.color : "#6B7280", fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", display: "flex", alignItems: "center", gap: 4 }}>
                    {f.emoji} {f.name}
                  </button>
                );
              })}
            </div>
            {folderId && (folders.find(f => f.id === folderId)?.subfolders || []).length > 0 && (
              <div style={{ marginTop: 8, display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button onClick={() => setSubfolderId("")} style={{ padding: "5px 12px", borderRadius: 20, border: `2px solid ${!subfolderId ? "#059669" : "#E5E7EB"}`, background: !subfolderId ? "#ECFDF5" : "#fff", color: !subfolderId ? "#059669" : "#6B7280", fontSize: 11, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
                  なし
                </button>
                {(folders.find(f => f.id === folderId)?.subfolders || []).map(sf => (
                  <button key={sf.id} onClick={() => setSubfolderId(sf.id)} style={{ padding: "5px 12px", borderRadius: 20, border: `2px solid ${subfolderId === sf.id ? "#059669" : "#E5E7EB"}`, background: subfolderId === sf.id ? "#ECFDF5" : "#fff", color: subfolderId === sf.id ? "#059669" : "#6B7280", fontSize: 11, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
                    {sf.emoji} {sf.name}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        {/* メモ */}
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
            <label style={{ fontSize: 13, fontWeight: 600, color: "#374151" }}>メモ <span style={{ fontWeight: 400, color: "#9CA3AF" }}>（任意）</span></label>
            <VoiceButton onResult={t => setMemo(prev => prev ? prev + " " + t : t)} />
          </div>
          <textarea value={memo} onChange={e => setMemo(e.target.value)} placeholder="メモを入力" rows={3} style={{ ...inputStyle, resize: "none", lineHeight: 1.6 }} />
        </div>

        <button onClick={save} disabled={!title.trim()} style={{ width: "100%", padding: "16px", borderRadius: 14, border: "none", background: title.trim() ? (th?.gradient || "linear-gradient(135deg, #34D399, #059669)") : "#E5E7EB", color: title.trim() ? "#fff" : "#9CA3AF", fontSize: 16, fontWeight: 700, cursor: title.trim() ? "pointer" : "default", boxShadow: title.trim() ? "0 4px 14px rgba(5,150,105,0.3)" : "none", fontFamily: "inherit", transition: "all 0.2s" }}>
          {isEdit ? "変更を保存する" : "TODOを追加する"}
        </button>
      </div>
    </div>
  );
};

// ─── SITUATION SCREEN ─────────────────────────────────────────────────────────
const SituationScreen = ({ setScreen, setSituation, categories, th, cs }) => (
  <div style={{ flex: 1, overflowY: "auto", paddingBottom: 40 }}>
    <div style={{ padding: "24px 20px 0" }}>
      <h2 style={{ fontSize: 22, fontWeight: 800, color: th?.text || "#111827", textAlign: "center" }}>今、なにをしていますか？</h2>
      <p style={{ fontSize: 13, color: th?.subtext || "#9CA3AF", textAlign: "center", marginTop: 8 }}>あなたの状況に合ったTODOをおすすめします！</p>
    </div>
    <div style={{ padding: "20px 20px 0", display: "flex", flexDirection: "column", gap: 10 }}>
      {categories.map((cat, i) => (
        <button key={cat.id} onClick={() => { setSituation(cat.id); setScreen("recommend"); }} style={{ display: "flex", alignItems: "center", gap: 14, padding: "16px 18px", borderRadius: cs?.radius || 16, border: cs?.hasBorder ? `1.5px solid ${th?.border || "#E5E7EB"}` : "none", background: th?.card || "#fff", cursor: "pointer", textAlign: "left", boxShadow: cs?.shadow || "0 1px 4px rgba(0,0,0,0.06)", animation: `fadeUp 0.3s ease ${i * 0.04}s both` }}>
          <span style={{ fontSize: 28, width: 40, textAlign: "center" }}>{cat.emoji}</span>
          <span style={{ fontSize: 16, fontWeight: 600, color: th?.text || "#111827" }}>{cat.label}</span>
          <span style={{ marginLeft: "auto", color: th?.border || "#D1D5DB", fontSize: 18 }}>›</span>
        </button>
      ))}
    </div>
  </div>
);

// ─── RECOMMEND SCREEN ─────────────────────────────────────────────────────────
const RecommendScreen = ({ todos, situation, setScreen, setEditTodo, onToggle, categories, th, cs }) => {
  const cat  = getCat(situation, categories);
  const recs = todos.filter(t => !t.done && t.category === situation);
  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 40 }}>
      <div style={{ padding: "20px 20px 0" }}>
        <button onClick={() => setScreen("situation")} style={{ fontSize: 13, color: th?.subtext || "#6B7280", background: "none", border: "none", cursor: "pointer", marginBottom: 16, fontFamily: "inherit" }}>← 戻る</button>
        <div style={{ padding: "20px", background: cat.bg, borderRadius: 20, textAlign: "center", marginBottom: 20 }}>
          <div style={{ fontSize: 40 }}>{cat.emoji}</div>
          <h2 style={{ fontSize: 18, fontWeight: 800, color: cat.color, marginTop: 8 }}>{cat.label}におすすめのTODO</h2>
        </div>
        {recs.length === 0 ? (
          <div style={{ textAlign: "center", padding: "32px 0", color: th?.subtext || "#9CA3AF" }}>
            <div style={{ fontSize: 40 }}>📭</div>
            <p style={{ fontSize: 14, marginTop: 8 }}>このカテゴリにTODOはありません</p>
            <button onClick={() => setScreen("add")} style={{ marginTop: 16, padding: "10px 20px", borderRadius: 12, background: cat.color, color: "#fff", border: "none", fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>TODOを追加する</button>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {recs.map((todo, i) => (
              <div key={todo.id} onClick={() => { setEditTodo(todo); setScreen("detail"); }} style={{ display: "flex", alignItems: "center", gap: 12, background: th?.card || "#fff", borderRadius: cs?.radius || 16, padding: "16px", boxShadow: cs?.shadow || "0 1px 4px rgba(0,0,0,0.06)", border: cs?.hasBorder ? `1.5px solid ${th?.border}` : "none", animation: `fadeUp 0.3s ease ${i * 0.05}s both`, cursor: "pointer" }}>
                <button onClick={e => { e.stopPropagation(); onToggle(todo.id); }} style={{ width: 26, height: 26, borderRadius: 99, border: `2px solid ${cat.color}`, background: "transparent", cursor: "pointer", flexShrink: 0 }} />
                <div style={{ flex: 1 }}>
                  <p style={{ fontSize: 15, fontWeight: 600, color: th?.text || "#111827" }}>{todo.title}</p>
                  <RepeatBadge repeat={todo.repeat} repeatTime={todo.repeatTime} />
                </div>
                <span style={{ color: th?.border || "#D1D5DB", fontSize: 18 }}>›</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// ─── LIST SCREEN ──────────────────────────────────────────────────────────────
const ListScreen = ({ todos, setScreen, setEditTodo, onToggle, onDelete, onRepeatDelete, categories, th, cs }) => {
  const [filter,   setFilter]   = useState("all");
  const [search,   setSearch]   = useState("");
  const [swipedId, setSwipedId] = useState(null);
  const touchStartX = useRef({});

  const filtered = todos
    .filter(t => filter === "all" ? true : filter === "done" ? isTodoDone(t) : !isTodoDone(t))
    .filter(t => t.title.includes(search));
  const cardBase = { background: th?.card || "#fff", borderRadius: cs?.radius || 14, boxShadow: cs?.shadow || "0 1px 3px rgba(0,0,0,0.06)", border: cs?.hasBorder ? `1.5px solid ${th?.border}` : "none" };

  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 100 }} onClick={() => swipedId && setSwipedId(null)}>
      <div style={{ padding: "20px 20px 0" }}>
        <h2 style={{ fontSize: 20, fontWeight: 800, color: th?.text || "#111827", marginBottom: 14 }}>すべてのTODO</h2>
        <div style={{ position: "relative", marginBottom: 12 }}>
          <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", fontSize: 16, color: th?.subtext || "#9CA3AF" }}>🔍</span>
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="検索..." style={{ width: "100%", padding: "10px 14px 10px 36px", borderRadius: 12, border: `1.5px solid ${th?.border || "#E5E7EB"}`, fontSize: 14, background: th?.bg || "#FAFAFA", outline: "none", boxSizing: "border-box", fontFamily: "inherit", color: th?.text || "#111827" }} />
        </div>
        <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
          {[["all", "すべて"], ["undone", "未完了"], ["done", "完了"]].map(([val, label]) => (
            <button key={val} onClick={() => setFilter(val)} style={{ padding: "6px 16px", borderRadius: 20, border: "none", cursor: "pointer", background: filter === val ? (th?.primary || "#059669") : (th?.primaryBg || "#F3F4F6"), color: filter === val ? "#fff" : (th?.subtext || "#6B7280"), fontSize: 13, fontWeight: 600, fontFamily: "inherit" }}>{label}</button>
          ))}
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {filtered.length === 0 && (
            <div style={{ textAlign: "center", padding: "32px 0", color: th?.subtext || "#9CA3AF" }}>
              <div style={{ fontSize: 36 }}>📭</div>
              <p style={{ fontSize: 14, marginTop: 8 }}>TODOが見つかりません</p>
            </div>
          )}
          {filtered.map((todo, i) => {
            const cat = getCat(todo.category, categories);
            const radius = cs?.radius || 14;
            return (
              <div key={todo.id} style={{ position: "relative", borderRadius: radius, overflow: "hidden" }}>
                {/* Delete reveal panel */}
                <div style={{ position: "absolute", right: 0, top: 0, bottom: 0, width: 80, background: "#EF4444", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 0 }}>
                  <button
                    onClick={e => {
                      e.stopPropagation();
                      if (todo.repeat && todo.repeat !== "none") {
                        onRepeatDelete(todo, today());
                      } else {
                        onDelete(todo.id);
                      }
                      setSwipedId(null);
                    }}
                    style={{ background: "none", border: "none", color: "#fff", fontSize: 26, cursor: "pointer", lineHeight: 1 }}
                  >🗑️</button>
                </div>
                {/* Swipeable main content */}
                <div
                  style={{ display: "flex", alignItems: "center", gap: 12, ...cardBase, padding: "14px", opacity: isTodoDone(todo) ? 0.6 : 1, animation: `fadeUp 0.3s ease ${i * 0.03}s both`, cursor: "pointer", transform: swipedId === todo.id ? "translateX(-80px)" : "translateX(0)", transition: "transform 0.2s ease", position: "relative", zIndex: 1 }}
                  onClick={() => { if (swipedId === todo.id) { setSwipedId(null); return; } setEditTodo(todo); setScreen("detail"); }}
                  onTouchStart={e => { touchStartX.current[todo.id] = e.touches[0].clientX; }}
                  onTouchEnd={e => {
                    const startX = touchStartX.current[todo.id];
                    if (startX == null) return;
                    const dx = startX - e.changedTouches[0].clientX;
                    if (dx > 50) setSwipedId(todo.id);
                    else if (dx < -20) setSwipedId(null);
                    delete touchStartX.current[todo.id];
                  }}
                >
                  <button onClick={e => { e.stopPropagation(); onToggle(todo.id); }} style={{ width: 24, height: 24, borderRadius: 99, border: `2px solid ${isTodoDone(todo) ? "#10B981" : cat.color}`, background: isTodoDone(todo) ? "#10B981" : "transparent", cursor: "pointer", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontSize: 13, fontWeight: 700 }}>{isTodoDone(todo) ? "✓" : ""}</button>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <p style={{ fontSize: 14, fontWeight: 600, color: th?.text || "#111827", textDecoration: isTodoDone(todo) ? "line-through" : "none", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{todo.title}</p>
                    <div style={{ display: "flex", gap: 4, marginTop: 4, alignItems: "center", flexWrap: "wrap" }}>
                      <CategoryBadge catId={todo.category} categories={categories} small />
                      <RepeatBadge repeat={todo.repeat} repeatTime={todo.repeatTime} />
                      <DeadlineBadge deadline={todo.deadline} deadlineTime={todo.deadlineTime} />
                      {todo.subtasks?.length > 0 && (
                        <span style={{ fontSize: 11, color: th?.primary || "#059669", fontWeight: 600, background: th?.primaryBg || "#ECFDF5", borderRadius: 20, padding: "2px 7px" }}>
                          {todo.subtasks.filter(s => s.done).length}/{todo.subtasks.length}
                        </span>
                      )}
                    </div>
                    {todo.subtasks?.length > 0 && (
                      <div style={{ marginTop: 6, height: 3, borderRadius: 99, background: th?.border || "#E5E7EB", overflow: "hidden" }}>
                        <div style={{ width: `${(todo.subtasks.filter(s => s.done).length / todo.subtasks.length) * 100}%`, height: "100%", background: th?.gradient || "linear-gradient(90deg,#34D399,#059669)" }} />
                      </div>
                    )}
                  </div>
                  <span style={{ fontSize: 11, color: th?.subtext || "#9CA3AF", flexShrink: 0, paddingLeft: 4 }}>←</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

// ─── DETAIL SCREEN ────────────────────────────────────────────────────────────
const DetailScreen = ({ todo, setScreen, setEditTodo, onToggle, onSubtaskToggle, onDelete, onRepeatDelete, categories, th, cs }) => {
  const [subtasks,       setSubtasks]       = useState(todo?.subtasks || []);
  const [confirmDelete,  setConfirmDelete]  = useState(false);
  if (!todo) { setScreen("list"); return null; }
  const occDate  = todo.occurrenceDate || null;
  const isDone   = isTodoDone(todo, occDate);
  const doneCount = subtasks.filter(s => s.done).length;
  const cardBase = { background: th?.card || "#fff", borderRadius: cs?.radius || 14, boxShadow: cs?.shadow || "none", border: cs?.hasBorder ? `1.5px solid ${th?.border}` : `1.5px solid ${th?.border || "#E5E7EB"}` };

  const handleSubtask = (stId) => {
    setSubtasks(prev => prev.map(s => s.id === stId ? { ...s, done: !s.done } : s));
    onSubtaskToggle(todo.id, stId);
  };

  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 40 }}>
      <div style={{ padding: "20px 20px 0" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
          <button onClick={() => setScreen("list")} style={{ fontSize: 13, color: th?.subtext || "#6B7280", background: "none", border: "none", cursor: "pointer", fontFamily: "inherit" }}>← 戻る</button>
          <button onClick={() => { setEditTodo(todo); setScreen("add"); }} style={{ fontSize: 13, color: th?.primary || "#059669", background: "none", border: "none", cursor: "pointer", fontWeight: 600, fontFamily: "inherit" }}>編集</button>
        </div>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 10 }}>
          <CategoryBadge catId={todo.category} categories={categories} />
          <RepeatBadge repeat={todo.repeat} repeatTime={todo.repeatTime} />
          {occDate && <span style={{ fontSize: 11, color: th?.subtext || "#6B7280", background: th?.primaryBg || "#F3F4F6", borderRadius: 20, padding: "2px 8px" }}>📅 {occDate}</span>}
        </div>
        <h1 style={{ fontSize: 24, fontWeight: 800, color: th?.text || "#111827", lineHeight: 1.3 }}>{todo.title}</h1>
        <div style={{ marginTop: 24, display: "flex", flexDirection: "column", gap: 14 }}>
          {subtasks.length > 0 && (
            <div style={{ padding: "16px", ...cardBase }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <p style={{ fontSize: 12, color: th?.text || "#374151", fontWeight: 600 }}>📋 サブタスク</p>
                <span style={{ fontSize: 12, color: th?.primary || "#059669", fontWeight: 700 }}>{doneCount}/{subtasks.length}</span>
              </div>
              <div style={{ height: 4, borderRadius: 99, background: th?.border || "#E5E7EB", marginBottom: 12, overflow: "hidden" }}>
                <div style={{ width: `${subtasks.length === 0 ? 0 : (doneCount / subtasks.length) * 100}%`, height: "100%", background: th?.gradient || "linear-gradient(90deg,#34D399,#059669)", transition: "width 0.4s ease" }} />
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {subtasks.map(st => (
                  <label key={st.id} style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}>
                    <div onClick={() => handleSubtask(st.id)} style={{ width: 20, height: 20, borderRadius: 6, border: `2px solid ${st.done ? (th?.primary || "#059669") : (th?.border || "#D1D5DB")}`, background: st.done ? (th?.primary || "#059669") : (th?.card || "#fff"), display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, cursor: "pointer" }}>
                      {st.done && <span style={{ fontSize: 11, color: "#fff", fontWeight: 700 }}>✓</span>}
                    </div>
                    <span style={{ fontSize: 14, color: st.done ? (th?.subtext || "#9CA3AF") : (th?.text || "#111827"), textDecoration: st.done ? "line-through" : "none", lineHeight: 1.5 }}>{st.text}</span>
                  </label>
                ))}
              </div>
            </div>
          )}
          {todo.deadline && (
            <div style={{ padding: "16px", background: th?.primaryBg || "#F3F4F6", borderRadius: cs?.radius || 14, border: cs?.hasBorder ? `1.5px solid ${th?.border}` : "none" }}>
              <p style={{ fontSize: 12, color: th?.subtext || "#6B7280", fontWeight: 600, marginBottom: 4 }}>{todo.deadlineTime ? "⏰" : "📅"} いつまでに</p>
              <p style={{ fontSize: 15, color: th?.text || "#111827", fontWeight: 700 }}>
                {new Date(todo.deadline + "T00:00:00").toLocaleDateString("ja-JP", { year: "numeric", month: "long", day: "numeric" })}
                {todo.deadlineTime && <span style={{ marginLeft: 8, fontSize: 18 }}>{todo.deadlineTime}</span>}
              </p>
            </div>
          )}
          {todo.memo && (
            <div style={{ padding: "16px", background: th?.primaryBg || "#F3F4F6", borderRadius: cs?.radius || 14, border: cs?.hasBorder ? `1.5px solid ${th?.border}` : "none" }}>
              <p style={{ fontSize: 12, color: th?.subtext || "#6B7280", fontWeight: 600, marginBottom: 4 }}>📝 メモ</p>
              <p style={{ fontSize: 14, color: th?.text || "#374151", lineHeight: 1.7, whiteSpace: "pre-wrap" }}>{todo.memo}</p>
            </div>
          )}
        </div>
        <button onClick={() => { onToggle(todo.id, occDate); setScreen("home"); }} style={{ width: "100%", marginTop: 28, padding: "16px", borderRadius: 14, border: "none", background: isDone ? (th?.primaryBg || "#F3F4F6") : (th?.gradient || "linear-gradient(135deg, #34D399, #059669)"), color: isDone ? (th?.subtext || "#6B7280") : "#fff", fontSize: 16, fontWeight: 700, cursor: "pointer", boxShadow: isDone ? "none" : "0 4px 14px rgba(5,150,105,0.3)", fontFamily: "inherit" }}>
          {isDone ? "未完了に戻す" : "完了にする ✓"}
        </button>
        <div style={{ marginTop: 12 }}>
          {!confirmDelete ? (
            <button
              onClick={() => {
                if (todo.repeat && todo.repeat !== "none") {
                  onRepeatDelete(todo, occDate || today());
                } else {
                  setConfirmDelete(true);
                }
              }}
              style={{ width: "100%", padding: "14px", borderRadius: 14, border: "1.5px solid #FCA5A5", background: "#FEF2F2", color: "#EF4444", fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}
            >
              🗑️ 削除する
            </button>
          ) : (
            <div>
              <p style={{ fontSize: 13, color: "#EF4444", textAlign: "center", marginBottom: 10, fontWeight: 600 }}>本当に削除しますか？</p>
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={() => setConfirmDelete(false)} style={{ flex: 1, padding: "14px", borderRadius: 14, border: `1.5px solid ${th?.border || "#E5E7EB"}`, background: th?.card || "#fff", color: th?.subtext || "#6B7280", fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>キャンセル</button>
                <button onClick={() => { onDelete(todo.id); setScreen("list"); }} style={{ flex: 1, padding: "14px", borderRadius: 14, border: "none", background: "#EF4444", color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>削除する</button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// ─── CALENDAR SCREEN ──────────────────────────────────────────────────────────
const CalendarScreen = ({ todos, setScreen, setEditTodo, onToggle, categories, th, cs }) => {
  const [viewDate,      setViewDate]      = useState(new Date());
  const [selectedDate,  setSelectedDate]  = useState(today());

  const year  = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const firstDayOfMonth = new Date(year, month, 1).getDay();
  const daysInMonth     = new Date(year, month + 1, 0).getDate();
  const todayStr        = today();

  const prevMonth = () => { const d = new Date(viewDate); d.setMonth(d.getMonth() - 1); setViewDate(d); };
  const nextMonth = () => { const d = new Date(viewDate); d.setMonth(d.getMonth() + 1); setViewDate(d); };

  // 指定日に表示すべきTODO（通常 + 繰り返しoccurrence）を返す
  const getCalendarTodosForDate = (dateStr) => {
    const result = [];
    todos.forEach(todo => {
      if (!todo.repeat || todo.repeat === "none") {
        if (todo.deadline === dateStr) result.push({ ...todo, occurrenceDate: dateStr });
      } else if (todo.deadline && isOccurrenceDate(todo, dateStr)) {
        result.push({ ...todo, occurrenceDate: dateStr });
      }
    });
    return result;
  };

  const selectedTodos = getCalendarTodosForDate(selectedDate);

  const DAY_NAMES = ["日", "月", "火", "水", "木", "金", "土"];

  const cardBase = { background: th?.card || "#fff", borderRadius: cs?.radius || 16, boxShadow: cs?.shadow || "0 1px 4px rgba(0,0,0,0.06)", border: cs?.hasBorder ? `1.5px solid ${th?.border}` : "none" };

  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 100 }}>
      <div style={{ padding: "20px 20px 0" }}>
        <h2 style={{ fontSize: 20, fontWeight: 800, color: th?.text || "#111827", marginBottom: 16 }}>📅 カレンダー</h2>

        {/* 月ナビゲーション */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12, padding: "12px 16px", ...cardBase }}>
          <button onClick={prevMonth} style={{ fontSize: 24, background: "none", border: "none", cursor: "pointer", color: th?.text || "#374151", lineHeight: 1, padding: "0 8px" }}>‹</button>
          <p style={{ fontSize: 16, fontWeight: 700, color: th?.text || "#111827" }}>{year}年{month + 1}月</p>
          <button onClick={nextMonth} style={{ fontSize: 24, background: "none", border: "none", cursor: "pointer", color: th?.text || "#374151", lineHeight: 1, padding: "0 8px" }}>›</button>
        </div>

        {/* カレンダーグリッド */}
        <div style={{ ...cardBase, padding: "14px 10px", marginBottom: 16 }}>
          {/* 曜日ヘッダー */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", marginBottom: 6 }}>
            {DAY_NAMES.map((d, i) => (
              <div key={d} style={{ textAlign: "center", fontSize: 11, fontWeight: 600, padding: "4px 0", color: i === 0 ? "#EF4444" : i === 6 ? "#3B82F6" : (th?.subtext || "#9CA3AF") }}>{d}</div>
            ))}
          </div>
          {/* 日付セル */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 2 }}>
            {Array.from({ length: firstDayOfMonth }, (_, i) => <div key={`e${i}`} />)}
            {Array.from({ length: daysInMonth }, (_, i) => {
              const day     = i + 1;
              const dateStr = `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
              const dayTodos = getCalendarTodosForDate(dateStr);
              const isToday    = dateStr === todayStr;
              const isSelected = dateStr === selectedDate;
              const dow = (firstDayOfMonth + i) % 7;
              return (
                <div key={day} onClick={() => setSelectedDate(dateStr)} style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "5px 2px", borderRadius: 10, cursor: "pointer", background: isSelected ? (th?.primary || "#059669") : isToday ? (th?.primaryBg || "#ECFDF5") : "transparent", minHeight: 42 }}>
                  <span style={{ fontSize: 13, fontWeight: isToday || isSelected ? 700 : 400, color: isSelected ? "#fff" : dow === 0 ? "#EF4444" : dow === 6 ? "#3B82F6" : (th?.text || "#374151") }}>{day}</span>
                  {dayTodos.length > 0 && (
                    <div style={{ display: "flex", gap: 2, marginTop: 3 }}>
                      {dayTodos.slice(0, 3).map((t, idx) => {
                        const occDone = isTodoDone(t, t.occurrenceDate);
                        return <div key={idx} style={{ width: 5, height: 5, borderRadius: 99, background: isSelected ? "rgba(255,255,255,0.8)" : occDone ? (th?.border || "#D1D5DB") : (th?.primary || "#059669") }} />;
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* 選択日のTODO一覧 */}
        <div>
          <h3 style={{ fontSize: 14, fontWeight: 700, color: th?.text || "#374151", marginBottom: 10 }}>
            {new Date(selectedDate + "T00:00:00").toLocaleDateString("ja-JP", { month: "long", day: "numeric", weekday: "short" })}のTODO
          </h3>
          {selectedTodos.length === 0 ? (
            <div style={{ textAlign: "center", padding: "24px", color: th?.subtext || "#9CA3AF", ...cardBase }}>
              <div style={{ fontSize: 32 }}>📭</div>
              <p style={{ fontSize: 13, marginTop: 8 }}>この日のTODOはありません</p>
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {selectedTodos.map(todo => {
                const cat    = getCat(todo.category, categories);
                const isDone = isTodoDone(todo, todo.occurrenceDate);
                return (
                  <div key={`${todo.id}-${todo.occurrenceDate}`} onClick={() => { setEditTodo(todo); setScreen("detail"); }} style={{ display: "flex", alignItems: "center", gap: 12, ...cardBase, padding: "14px", opacity: isDone ? 0.5 : 1, cursor: "pointer" }}>
                    <button onClick={e => { e.stopPropagation(); onToggle(todo.id, todo.occurrenceDate); }} style={{ width: 24, height: 24, borderRadius: 99, border: `2px solid ${isDone ? "#10B981" : cat.color}`, background: isDone ? "#10B981" : "transparent", display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontSize: 13, fontWeight: 700, flexShrink: 0, cursor: "pointer" }}>{isDone ? "✓" : ""}</button>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <p style={{ fontSize: 14, fontWeight: 600, color: th?.text || "#111827", textDecoration: isDone ? "line-through" : "none", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{todo.title}</p>
                      <div style={{ display: "flex", gap: 4, marginTop: 4, flexWrap: "wrap" }}>
                        <CategoryBadge catId={todo.category} categories={categories} small />
                        <RepeatBadge repeat={todo.repeat} repeatTime={todo.repeatTime} />
                        {todo.deadlineTime && (
                          <span style={{ fontSize: 10, color: "#F97316", fontWeight: 600, background: "#FFF7ED", borderRadius: 20, padding: "2px 7px" }}>⏰ {todo.deadlineTime}</span>
                        )}
                      </div>
                    </div>
                    <span style={{ color: th?.border || "#D1D5DB", fontSize: 18 }}>›</span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// ─── SETTINGS SCREEN ──────────────────────────────────────────────────────────
// ─── GROWTH GRAPH SCREEN ─────────────────────────────────────────────────────
const GrowthGraphScreen = ({ todos, streak, setScreen, th, cs }) => {
  const todayStr = today();

  const getDayStr = (offsetDays) => {
    const d = new Date();
    d.setDate(d.getDate() + offsetDays);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  };

  const countCompletedOn = (dateStr) => {
    let count = 0;
    todos.forEach(t => {
      if (t.repeat && t.repeat !== "none") {
        if ((t.completedDates || []).includes(dateStr)) count++;
      } else if (t.done && t.doneDate === dateStr) {
        count++;
      }
    });
    return count;
  };

  const weekData = Array.from({ length: 7 }, (_, i) => {
    const dateStr = getDayStr(i - 6);
    const d = new Date(dateStr + "T00:00:00");
    const label = `${d.getMonth()+1}/${d.getDate()}`;
    return { date: label, 完了数: countCompletedOn(dateStr), isToday: dateStr === todayStr };
  });

  const monthData = Array.from({ length: 30 }, (_, i) => {
    const dateStr = getDayStr(i - 29);
    const d = new Date(dateStr + "T00:00:00");
    const label = `${d.getMonth()+1}/${d.getDate()}`;
    return { date: label, 完了数: countCompletedOn(dateStr) };
  });

  const weekTotal = weekData.reduce((s, d) => s + d.完了数, 0);
  const weekAvg   = weekData.length ? (weekTotal / weekData.length).toFixed(1) : 0;
  const monthTotal = monthData.reduce((s, d) => s + d.完了数, 0);
  const totalDone  = todos.filter(t => t.done || (t.completedDates || []).length > 0).reduce((s, t) => {
    if (t.repeat && t.repeat !== "none") return s + (t.completedDates || []).length;
    return s + (t.done ? 1 : 0);
  }, 0);

  const cardBase = { background: th.card, borderRadius: cs.radius, boxShadow: cs.shadow, border: cs.hasBorder ? `1.5px solid ${th.border}` : "none" };
  const primary = th.primary || "#059669";

  const StatBox = ({ label, value, unit }) => (
    <div style={{ flex: 1, textAlign: "center", padding: "14px 8px" }}>
      <p style={{ fontSize: 24, fontWeight: 900, color: primary }}>{value}<span style={{ fontSize: 13, fontWeight: 600, color: th.subtext }}>{unit}</span></p>
      <p style={{ fontSize: 11, color: th.subtext, marginTop: 4, lineHeight: 1.4 }}>{label}</p>
    </div>
  );

  const CustomBar = (props) => {
    const { x, y, width, height, isToday } = props;
    return <rect x={x} y={y} width={width} height={height} rx={4} fill={isToday ? primary : `${primary}66`} />;
  };

  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 40 }}>
      <div style={{ padding: "20px 20px 0" }}>
        <h2 style={{ fontSize: 20, fontWeight: 800, color: th.text, marginBottom: 20, paddingTop: 8 }}>📊 成長グラフ</h2>

        {/* 統計サマリー */}
        <div style={{ ...cardBase, display: "flex", marginBottom: 14 }}>
          <StatBox label="累計完了" value={totalDone} unit="個" />
          <div style={{ width: 1, background: th.border, margin: "12px 0" }} />
          <StatBox label="連続記録" value={streak.current || 0} unit="日" />
          <div style={{ width: 1, background: th.border, margin: "12px 0" }} />
          <StatBox label="最長記録" value={streak.max || 0} unit="日" />
        </div>
        <div style={{ ...cardBase, display: "flex", marginBottom: 20 }}>
          <StatBox label="今週の完了" value={weekTotal} unit="個" />
          <div style={{ width: 1, background: th.border, margin: "12px 0" }} />
          <StatBox label="今月の完了" value={monthTotal} unit="個" />
          <div style={{ width: 1, background: th.border, margin: "12px 0" }} />
          <StatBox label="週平均" value={weekAvg} unit="個/日" />
        </div>

        {/* 週間棒グラフ */}
        <div style={{ ...cardBase, padding: "18px 16px", marginBottom: 14 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <p style={{ fontSize: 14, fontWeight: 700, color: th.text }}>週間達成グラフ</p>
            <p style={{ fontSize: 12, color: th.subtext }}>今週の平均：<span style={{ color: primary, fontWeight: 700 }}>{weekAvg}個</span>/日</p>
          </div>
          <ResponsiveContainer width="100%" height={160}>
            <BarChart data={weekData} margin={{ top: 4, right: 4, left: -24, bottom: 0 }}>
              <XAxis dataKey="date" tick={{ fontSize: 10, fill: th.subtext }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fontSize: 10, fill: th.subtext }} axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip contentStyle={{ borderRadius: 10, border: "none", boxShadow: "0 4px 12px rgba(0,0,0,0.1)", fontSize: 12 }} cursor={{ fill: "rgba(0,0,0,0.04)" }} />
              <Bar dataKey="完了数" shape={<CustomBar />} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* 月間折れ線グラフ */}
        <div style={{ ...cardBase, padding: "18px 16px" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <p style={{ fontSize: 14, fontWeight: 700, color: th.text }}>月間達成グラフ</p>
            <p style={{ fontSize: 12, color: th.subtext }}>今月の合計：<span style={{ color: primary, fontWeight: 700 }}>{monthTotal}個</span>完了</p>
          </div>
          <ResponsiveContainer width="100%" height={160}>
            <LineChart data={monthData} margin={{ top: 4, right: 4, left: -24, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={th.border} vertical={false} />
              <XAxis dataKey="date" tick={{ fontSize: 9, fill: th.subtext }} axisLine={false} tickLine={false} interval={6} />
              <YAxis tick={{ fontSize: 10, fill: th.subtext }} axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip contentStyle={{ borderRadius: 10, border: "none", boxShadow: "0 4px 12px rgba(0,0,0,0.1)", fontSize: 12 }} />
              <Line type="monotone" dataKey="完了数" stroke={primary} strokeWidth={2.5} dot={false} activeDot={{ r: 5, fill: primary }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

// ─── COMPLETED HISTORY SCREEN ────────────────────────────────────────────────
const CompletedHistoryScreen = ({ todos, setScreen, th, cs }) => {
  const [search, setSearch] = useState("");

  const completedItems = [];
  todos.forEach(todo => {
    if (todo.repeat && todo.repeat !== "none") {
      (todo.completedDates || []).forEach(date => {
        completedItems.push({ ...todo, completedOn: date });
      });
    } else if (todo.done) {
      completedItems.push({ ...todo, completedOn: todo.doneDate || null });
    }
  });

  const filtered = search.trim()
    ? completedItems.filter(t => t.title.includes(search.trim()))
    : completedItems;

  const grouped = {};
  filtered.forEach(item => {
    const key = item.completedOn || "日付不明";
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(item);
  });

  const sortedDates = Object.keys(grouped).sort((a, b) => {
    if (a === "日付不明") return 1;
    if (b === "日付不明") return -1;
    return b.localeCompare(a);
  });

  const formatDateLabel = (dateStr) => {
    if (dateStr === "日付不明") return "日付不明";
    const d = new Date(dateStr + "T00:00:00");
    if (isNaN(d)) return dateStr;
    return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
  };

  const cardBase = { background: th.card, borderRadius: cs.radius, boxShadow: cs.shadow, border: cs.hasBorder ? `1.5px solid ${th.border}` : "none" };

  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 40 }}>
      <div style={{ padding: "20px 20px 0" }}>
        <button onClick={() => setScreen("settings")} style={{ fontSize: 13, color: th.subtext, background: "none", border: "none", cursor: "pointer", marginBottom: 16, fontFamily: "inherit" }}>← 戻る</button>
        <h2 style={{ fontSize: 20, fontWeight: 800, color: th.text, marginBottom: 16 }}>✅ 完了済みタスク履歴</h2>

        <input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="タスクを検索..."
          style={{ width: "100%", padding: "10px 14px", borderRadius: 12, border: `1.5px solid ${th.border}`, background: th.card, color: th.text, fontSize: 14, outline: "none", fontFamily: "inherit", boxSizing: "border-box", marginBottom: 20 }}
        />

        {sortedDates.length === 0 ? (
          <div style={{ textAlign: "center", padding: "48px 0" }}>
            <div style={{ fontSize: 44, marginBottom: 12 }}>📭</div>
            <p style={{ fontSize: 16, fontWeight: 700, color: th.text }}>完了済みタスクがありません</p>
            <p style={{ fontSize: 13, color: th.subtext, marginTop: 8 }}>タスクを完了するとここに表示されます</p>
          </div>
        ) : (
          sortedDates.map(dateKey => (
            <div key={dateKey} style={{ marginBottom: 22 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                <p style={{ fontSize: 13, fontWeight: 700, color: th.subtext }}>{formatDateLabel(dateKey)}</p>
                <span style={{ fontSize: 11, color: th.subtext }}>（{grouped[dateKey].length}件完了）</span>
              </div>
              <div style={{ ...cardBase, overflow: "hidden" }}>
                {grouped[dateKey].map((item, i) => (
                  <div key={`${item.id}-${dateKey}-${i}`} style={{ display: "flex", alignItems: "center", gap: 12, padding: "13px 16px", borderBottom: i < grouped[dateKey].length - 1 ? `1px solid ${th.border}` : "none" }}>
                    <div style={{ width: 22, height: 22, borderRadius: 99, background: "#059669", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                      <span style={{ color: "#fff", fontSize: 12, fontWeight: 700 }}>✓</span>
                    </div>
                    <p style={{ flex: 1, fontSize: 14, color: th.text, textDecoration: "line-through", opacity: 0.65, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{item.title}</p>
                  </div>
                ))}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

