const SettingsScreen = ({ user, onLogout, settings, th, cs, setScreen, unlockedRewards, streak }) => {
  const cardBase = { background: th.card, borderRadius: cs.radius, boxShadow: cs.shadow, border: cs.hasBorder ? `1.5px solid ${th.border}` : "none" };
  const topBadge = unlockedRewards.includes("streak_365") ? "👑" : unlockedRewards.includes("streak_100") ? "💎" : unlockedRewards.includes("streak_30") ? "⚡" : unlockedRewards.includes("streak_7") ? "🔥" : null;

  const todayStr = today();
  const prevDay = new Date(); prevDay.setDate(prevDay.getDate() - 1);
  const yest = `${prevDay.getFullYear()}-${String(prevDay.getMonth()+1).padStart(2,"0")}-${String(prevDay.getDate()).padStart(2,"0")}`;
  const isAlive = streak.lastDate === todayStr || streak.lastDate === yest;
  const displayStreak = isAlive ? (streak.current || 0) : 0;

  const SectionLabel = ({ text }) => (
    <p style={{ fontSize: 11, fontWeight: 700, color: th.subtext, letterSpacing: 1.5, marginTop: 24, marginBottom: 10 }}>{text}</p>
  );

  const MenuItem = ({ icon, iconBg, label, sub, onPress, last }) => (
    <button onClick={onPress} style={{ width: "100%", padding: "14px 16px", display: "flex", alignItems: "center", gap: 14, cursor: "pointer", background: "none", border: "none", borderBottom: last ? "none" : `1px solid ${th.border}`, textAlign: "left", fontFamily: "inherit" }}>
      <div style={{ width: 36, height: 36, borderRadius: 10, background: iconBg, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, flexShrink: 0 }}>{icon}</div>
      <div style={{ flex: 1 }}>
        <p style={{ fontSize: 14, fontWeight: 600, color: th.text }}>{label}</p>
        {sub && <p style={{ fontSize: 12, color: th.subtext, marginTop: 1 }}>{sub}</p>}
      </div>
      <span style={{ color: th.subtext, fontSize: 18 }}>›</span>
    </button>
  );

  return (
    <div style={{ flex: 1, overflowY: "auto", paddingBottom: 40, background: th.bg }}>
      <div style={{ padding: "20px 20px 0" }}>
        <h2 style={{ fontSize: 20, fontWeight: 800, color: th.text, marginBottom: 20, paddingTop: 8 }}>⚙️ 設定</h2>

        {/* ① プロフィールカード */}
        <div style={{ ...cardBase, padding: "20px 16px", display: "flex", alignItems: "center", gap: 16, marginBottom: 0 }}>
          <div style={{ position: "relative", flexShrink: 0 }}>
            {user?.photoURL ? (
              <img src={user.photoURL} alt="" style={{ width: 60, height: 60, borderRadius: 99, objectFit: "cover", border: `2px solid ${th.border}` }} />
            ) : (
              <div style={{ width: 60, height: 60, borderRadius: 99, background: topBadge === "👑" ? "linear-gradient(135deg,#FDE68A,#F59E0B)" : th.gradient, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 26, fontWeight: 700, color: "#fff" }}>
                {(user?.displayName || user?.email || "U")[0].toUpperCase()}
              </div>
            )}
            {topBadge && <span style={{ position: "absolute", bottom: -2, right: -2, fontSize: 18, animation: topBadge === "👑" ? "pulse 2s infinite" : "none" }}>{topBadge}</span>}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <p style={{ fontSize: 16, fontWeight: 700, color: th.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{user?.displayName || "ユーザー"}</p>
            <p style={{ fontSize: 12, color: th.subtext, marginTop: 3, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{user?.email}</p>
            {displayStreak > 0 && <p style={{ fontSize: 11, color: th.primary, fontWeight: 700, marginTop: 4 }}>🔥 {displayStreak}日連続達成中</p>}
          </div>
        </div>

        {/* ② メインメニュー */}
        <SectionLabel text="メニュー" />
        <div style={{ ...cardBase, overflow: "hidden" }}>
          <MenuItem icon="📁" iconBg={th.primaryBg} label="フォルダ管理" sub="フォルダの追加・編集・削除" onPress={() => setScreen("folderManagement")} />
          <MenuItem icon="🔔" iconBg="#FEF3C7" label="通知設定" sub={settings.notification ? "通知オン" : "通知オフ"} onPress={() => setScreen("notificationSettings")} />
          <MenuItem icon="🎨" iconBg="#F5F3FF" label="テーマ・デザイン" sub="テーマ・フォント・スタイル" onPress={() => setScreen("themeSettings")} last />
        </div>

        {/* ③ データ */}
        <SectionLabel text="データ" />
        <div style={{ ...cardBase, overflow: "hidden" }}>
          <MenuItem icon="✅" iconBg="#ECFDF5" label="完了済みタスク履歴" onPress={() => setScreen("completedHistory")} />
          <MenuItem icon="📋" iconBg={th.primaryBg} label="すべてのTODO" onPress={() => setScreen("list")} last />
        </div>

        {/* ④ サポート */}
        <SectionLabel text="サポート" />
        <div style={{ ...cardBase, overflow: "hidden" }}>
          <MenuItem icon="ℹ️" iconBg="#EFF6FF" label="アプリについて" sub="TODO LIFE v1.5.0" onPress={() => setScreen("about")} />
          <MenuItem icon="💬" iconBg="#F0FDF4" label="フィードバックを送る" onPress={() => window.open("mailto:feedback@todo-life.app")} last />
        </div>

        {/* ⑤ ログアウト */}
        <div style={{ marginTop: 32 }}>
          <button onClick={onLogout} style={{ width: "100%", padding: "16px", borderRadius: cs.radius, border: "none", background: "#FEF2F2", color: "#EF4444", fontSize: 15, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
            ログアウト
          </button>
        </div>
      </div>
    </div>
  );
};

// ─── ONBOARDING SCREEN ───────────────────────────────────────────────────────
const OnboardingScreen = ({ onComplete, user }) => {
  const [step, setStep] = useState(1);
  const [issues, setIssues] = useState([]);
  const [goals, setGoals] = useState([]);
  const [problematicApps, setProblematicApps] = useState([]);
  const [screenTime, setScreenTime] = useState("");
  const [diagnosisLoading, setDiagnosisLoading] = useState(false);
  const [diagnosis, setDiagnosis] = useState(null);
  const [suggestedTodos, setSuggestedTodos] = useState([]);
  const [issueOther, setIssueOther] = useState("");
  const [goalOther, setGoalOther] = useState("");
  const [appOther, setAppOther] = useState("");

  const toggle = (arr, setArr, val) =>
    setArr(prev => prev.includes(val) ? prev.filter(v => v !== val) : [...prev, val]);

  const generateDiagnosis = async () => {
    setDiagnosisLoading(true);
    let diagType;
    const allIssues = [...issues, ...(issueOther.trim() ? [issueOther.trim()] : [])];
    if (allIssues.includes("SNSをやめられない")) diagType = DIAGNOSIS_TYPES[0];
    else if (allIssues.includes("時間の使い方が下手") || allIssues.includes("やりたいことが続かない")) diagType = DIAGNOSIS_TYPES[1];
    else if (allIssues.includes("仕事・勉強の効率が悪い")) diagType = DIAGNOSIS_TYPES[2];
    else if (allIssues.includes("生活習慣が乱れている") || allIssues.includes("ダイエットが続かない")) diagType = DIAGNOSIS_TYPES[3];
    else diagType = DIAGNOSIS_TYPES[4];

    const allGoals = [...goals, ...(goalOther.trim() ? [goalOther.trim()] : [])];
    const todoMap = {
      "SNS依存を克服したい":          ["食事中はスマホを伏せる", "朝起きて30分はスマホを見ない", "通知をオフにする時間を作る"],
      "毎日継続できる自分になりたい":  ["今日のMITを1つ決める", "毎日TODO LIFEを開く", "小さな約束を自分に守る"],
      "健康的な体を手に入れたい":      ["10分間ウォーキング", "野菜を1品増やす", "22時にはスマホを置く"],
      "仕事・勉強で成果を出したい":    ["集中30分タイマーをセット", "仕事前にタスクを書き出す", "教材を1ページ読む"],
      "生活習慣を整えたい":            ["起床時間を固定する", "就寝前にスマホを置く", "食事の時間を決める"],
      "自分に自信をつけたい":          ["今日の良かったことを1つ書く", "得意なことを1つリスト化する", "鏡の前で深呼吸する"],
      "ダイエットを成功させたい":      ["体重を毎朝記録する", "階段を使う", "甘い飲み物を水に替える"],
      "時間を有効活用したい":          ["朝にその日のタスクを書き出す", "スマホ使用時間を計測する", "余白の時間を意図的に作る"],
    };
    const todos = [];
    for (const goal of allGoals.slice(0, 3)) {
      const items = todoMap[goal] || [];
      if (items[0]) todos.push(items[0]);
    }
    if (todos.length < 3) todos.push("毎日TODO LIFEを開く", "今日の良かったことを1つ書く");
    setSuggestedTodos(todos.slice(0, 5));
    await new Promise(r => setTimeout(r, 2000));
    setDiagnosis(diagType);
    setDiagnosisLoading(false);
  };

  const handleNext = async () => {
    if (step < 4) { setStep(s => s + 1); return; }
    setStep(5);
    await generateDiagnosis();
  };

  const handleComplete = async (addTodos) => {
    const profile = { issues, goals, problematicApps, screenTime, diagnosis: diagnosis?.key, completedAt: today() };
    if (user) await setDoc(doc(db, "users", user.uid), { profile }, { merge: true });
    onComplete(profile, addTodos ? suggestedTodos : []);
  };

  const btnStyle = (active) => ({
    padding: "11px 14px", borderRadius: 12, cursor: "pointer", textAlign: "left", fontFamily: "inherit",
    fontSize: 13, fontWeight: active ? 700 : 500,
    border: `2px solid ${active ? "#059669" : "#E5E7EB"}`,
    background: active ? "#ECFDF5" : "#fff", color: active ? "#059669" : "#374151",
  });

  const canNext = (step === 1 && issues.length > 0) || (step === 2 && goals.length > 0) ||
                  step === 3 || (step === 4 && !!screenTime);

  return (
    <div style={{ position: "absolute", inset: 0, background: "#fff", display: "flex", flexDirection: "column", zIndex: 500 }}>
      <div style={{ padding: "20px 24px 0", display: "flex", gap: 6 }}>
        {[1,2,3,4,5].map(s => (
          <div key={s} style={{ flex: 1, height: 4, borderRadius: 99, background: s <= step ? "#059669" : "#E5E7EB", transition: "background 0.3s" }} />
        ))}
      </div>
      <div style={{ flex: 1, overflowY: "auto", padding: "24px 24px 0" }}>
        {step === 1 && (
          <div style={{ animation: "fadeUp 0.3s ease" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>🤔</div>
            <h2 style={{ fontSize: 22, fontWeight: 800, color: "#111827", marginBottom: 6 }}>今の自分に当てはまるものを選んでください</h2>
            <p style={{ fontSize: 13, color: "#6B7280", marginBottom: 20, lineHeight: 1.6 }}>複数選択可</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {ISSUES_OPTIONS.map(o => (
                <button key={o} onClick={() => toggle(issues, setIssues, o)} style={btnStyle(issues.includes(o))}>
                  {issues.includes(o) ? "✅ " : "○ "}{o}
                </button>
              ))}
              <div style={{ display: "flex", gap: 8, alignItems: "center", padding: "6px 0" }}>
                <input value={issueOther} onChange={e => setIssueOther(e.target.value)} placeholder="その他（自由入力）"
                  style={{ flex: 1, padding: "10px 12px", borderRadius: 12, border: `2px solid ${issueOther.trim() ? "#059669" : "#E5E7EB"}`, background: issueOther.trim() ? "#ECFDF5" : "#fff", fontSize: 13, outline: "none", fontFamily: "inherit", color: "#374151" }} />
              </div>
            </div>
          </div>
        )}
        {step === 2 && (
          <div style={{ animation: "fadeUp 0.3s ease" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>🎯</div>
            <h2 style={{ fontSize: 22, fontWeight: 800, color: "#111827", marginBottom: 6 }}>なりたい自分を選んでください</h2>
            <p style={{ fontSize: 13, color: "#6B7280", marginBottom: 20, lineHeight: 1.6 }}>複数選択可</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {GOALS_OPTIONS.map(o => (
                <button key={o} onClick={() => toggle(goals, setGoals, o)} style={btnStyle(goals.includes(o))}>
                  {goals.includes(o) ? "✅ " : "○ "}{o}
                </button>
              ))}
              <div style={{ display: "flex", gap: 8, alignItems: "center", padding: "6px 0" }}>
                <input value={goalOther} onChange={e => setGoalOther(e.target.value)} placeholder="その他（自由入力）"
                  style={{ flex: 1, padding: "10px 12px", borderRadius: 12, border: `2px solid ${goalOther.trim() ? "#059669" : "#E5E7EB"}`, background: goalOther.trim() ? "#ECFDF5" : "#fff", fontSize: 13, outline: "none", fontFamily: "inherit", color: "#374151" }} />
              </div>
            </div>
          </div>
        )}
        {step === 3 && (
          <div style={{ animation: "fadeUp 0.3s ease" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>📱</div>
            <h2 style={{ fontSize: 22, fontWeight: 800, color: "#111827", marginBottom: 6 }}>使いすぎてるアプリは？</h2>
            <p style={{ fontSize: 13, color: "#6B7280", marginBottom: 20, lineHeight: 1.6 }}>時間を使いすぎているアプリを選んでください（複数選択可）</p>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 10 }}>
              {APPS_OPTIONS.map(a => (
                <button key={a.id} onClick={() => toggle(problematicApps, setProblematicApps, a.id)}
                  style={{ ...btnStyle(problematicApps.includes(a.id)), textAlign: "center", padding: "16px 8px" }}>
                  <div style={{ fontSize: 28, marginBottom: 4 }}>{a.emoji}</div>
                  <div style={{ fontSize: 12 }}>{a.label}</div>
                </button>
              ))}
            </div>
            <div style={{ marginTop: 10 }}>
              <input value={appOther} onChange={e => setAppOther(e.target.value)} placeholder="その他（自由入力）"
                style={{ width: "100%", padding: "10px 12px", borderRadius: 12, border: `2px solid ${appOther.trim() ? "#059669" : "#E5E7EB"}`, background: appOther.trim() ? "#ECFDF5" : "#fff", fontSize: 13, outline: "none", fontFamily: "inherit", color: "#374151", boxSizing: "border-box" }} />
            </div>
          </div>
        )}
        {step === 4 && (
          <div style={{ animation: "fadeUp 0.3s ease" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>⏱️</div>
            <h2 style={{ fontSize: 22, fontWeight: 800, color: "#111827", marginBottom: 6 }}>1日のスマホ時間は？</h2>
            <p style={{ fontSize: 13, color: "#6B7280", marginBottom: 20, lineHeight: 1.6 }}>現在の平均スクリーンタイムを教えてください</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {SCREEN_TIME_OPTIONS.map(o => (
                <button key={o} onClick={() => setScreenTime(o)} style={btnStyle(screenTime === o)}>
                  {screenTime === o ? "✅ " : "○ "}{o}
                </button>
              ))}
            </div>
          </div>
        )}
        {step === 5 && (
          <div style={{ animation: "fadeUp 0.3s ease" }}>
            {diagnosisLoading ? (
              <div style={{ textAlign: "center", paddingTop: 40 }}>
                <div style={{ fontSize: 48, marginBottom: 16, animation: "pulse 1s infinite" }}>🤖</div>
                <h2 style={{ fontSize: 20, fontWeight: 800, color: "#111827", marginBottom: 8 }}>AIが分析中...</h2>
                <p style={{ fontSize: 13, color: "#6B7280", lineHeight: 1.6, marginBottom: 24 }}>あなたの情報をもとに<br />最適なプランを作成しています</p>
                <div style={{ display: "flex", justifyContent: "center", gap: 8, flexWrap: "wrap" }}>
                  {["分析中", "パターン検出", "プラン生成"].map((t, i) => (
                    <div key={t} style={{ padding: "6px 12px", borderRadius: 20, background: "#ECFDF5", color: "#059669", fontSize: 11, fontWeight: 600, animation: `pulse 1s infinite ${i * 0.3}s` }}>{t}</div>
                  ))}
                </div>
              </div>
            ) : diagnosis && (
              <div>
                <div style={{ textAlign: "center", marginBottom: 20 }}>
                  <div style={{ fontSize: 52, marginBottom: 8 }}>{diagnosis.emoji}</div>
                  <div style={{ display: "inline-block", padding: "3px 14px", borderRadius: 20, background: "#ECFDF5", color: "#059669", fontSize: 12, fontWeight: 700, marginBottom: 8 }}>診断結果</div>
                  <h2 style={{ fontSize: 22, fontWeight: 800, color: "#111827" }}>「{diagnosis.typeName}」タイプ</h2>
                </div>
                <div style={{ padding: "14px", background: "#F9FAFB", borderRadius: 14, marginBottom: 14 }}>
                  <p style={{ fontSize: 13, color: "#374151", lineHeight: 1.7 }}>{diagnosis.message}</p>
                </div>
                <div style={{ marginBottom: 16 }}>
                  <p style={{ fontSize: 13, fontWeight: 700, color: "#374151", marginBottom: 10 }}>🎯 あなたの3つの課題</p>
                  {diagnosis.challenges.map((c, i) => (
                    <div key={i} style={{ display: "flex", gap: 10, padding: "8px 0", borderBottom: i < 2 ? "1px solid #F3F4F6" : "none" }}>
                      <span style={{ color: "#EF4444", fontWeight: 700, flexShrink: 0 }}>{i+1}.</span>
                      <span style={{ fontSize: 13, color: "#374151" }}>{c}</span>
                    </div>
                  ))}
                </div>
                <div>
                  <p style={{ fontSize: 13, fontWeight: 700, color: "#374151", marginBottom: 10 }}>✨ おすすめのTODO（{suggestedTodos.length}件）</p>
                  {suggestedTodos.map((t, i) => (
                    <div key={i} style={{ display: "flex", gap: 10, padding: "8px 12px", background: "#ECFDF5", borderRadius: 10, marginBottom: 6 }}>
                      <span>📋</span>
                      <span style={{ fontSize: 13, color: "#059669", fontWeight: 500 }}>{t}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
      <div style={{ padding: "16px 24px 44px", flexShrink: 0 }}>
        {step < 5 ? (
          <button onClick={handleNext} disabled={!canNext} style={{ width: "100%", padding: "16px", borderRadius: 14, border: "none", background: canNext ? "linear-gradient(135deg,#34D399,#059669)" : "#E5E7EB", color: canNext ? "#fff" : "#9CA3AF", fontSize: 16, fontWeight: 700, cursor: canNext ? "pointer" : "default", fontFamily: "inherit" }}>
            {step === 4 ? "AIに診断してもらう 🤖" : "次へ →"}
          </button>
        ) : !diagnosisLoading && diagnosis && (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <button onClick={() => handleComplete(true)} style={{ width: "100%", padding: "16px", borderRadius: 14, border: "none", background: "linear-gradient(135deg,#34D399,#059669)", color: "#fff", fontSize: 16, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
              TODOを追加して始める ✅
            </button>
            <button onClick={() => handleComplete(false)} style={{ width: "100%", padding: "14px", borderRadius: 14, border: "1.5px solid #E5E7EB", background: "#fff", color: "#6B7280", fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
              スキップして始める
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

// ─── PAYWALL SCREEN ───────────────────────────────────────────────────────────
const PaywallScreen = ({ trialEndDate, onClose, onSelectPlan, th }) => {
  const [selectedPlan, setSelectedPlan] = useState("yearly_special");
  const [loading, setLoading] = useState(false);
  const [thankyou, setThankyou] = useState(false);
  const todayD = new Date(today() + "T00:00:00");
  const trialEndD = new Date((trialEndDate || today()) + "T00:00:00");
  const trialLeft = Math.max(0, Math.ceil((trialEndD - todayD) / 86400000));
  const isExpired = todayD > trialEndD;

  const handleSubscribe = async () => {
    setLoading(true);
    await new Promise(r => setTimeout(r, 900));
    onSelectPlan(selectedPlan);
    setLoading(false);
    setThankyou(true);
  };

  if (thankyou) return (
    <div style={{ position: "absolute", inset: 0, background: "#fff", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", zIndex: 500, padding: "32px 24px", textAlign: "center" }}>
      <div style={{ fontSize: 72, marginBottom: 20 }}>🎉</div>
      <h1 style={{ fontSize: 24, fontWeight: 800, color: "#111827", marginBottom: 12 }}>ありがとうございます！</h1>
      <p style={{ fontSize: 16, color: "#059669", fontWeight: 700, marginBottom: 8 }}>続けましょう！</p>
      <p style={{ fontSize: 13, color: "#6B7280", lineHeight: 1.6, marginBottom: 32 }}>プレミアムプランへようこそ。<br />あなたの挑戦を全力でサポートします。</p>
      <button onClick={onClose} style={{ padding: "16px 40px", borderRadius: 14, border: "none", background: "linear-gradient(135deg,#34D399,#059669)", color: "#fff", fontSize: 16, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
        はじめる ✨
      </button>
    </div>
  );

  return (
    <div style={{ position: "absolute", inset: 0, background: "#fff", display: "flex", flexDirection: "column", zIndex: 500, overflowY: "auto" }}>
      <div style={{ background: "linear-gradient(135deg,#059669,#34D399)", padding: "44px 24px 28px", textAlign: "center" }}>
        <div style={{ fontSize: 48, marginBottom: 10 }}>✨</div>
        <h1 style={{ fontSize: 24, fontWeight: 800, color: "#fff", marginBottom: 6 }}>TODO LIFE Premium</h1>
        <p style={{ fontSize: 13, color: "rgba(255,255,255,0.85)" }}>
          {isExpired ? "無料トライアル期間が終了しました" : `無料トライアル残り ${trialLeft} 日`}
        </p>
      </div>
      <div style={{ padding: "24px" }}>
        <p style={{ fontSize: 13, fontWeight: 700, color: "#374151", marginBottom: 12 }}>プレミアムでできること</p>
        {[
          ["🤖 AI TODOサジェスト", "無制限", "1日1回"],
          ["🎨 テーマ",            "全テーマ",  "基本3種"],
          ["✅ TODOの数",          "無制限",   "月20件"],
          ["📊 ドーパミンスコア",   "✓",       "×"],
          ["📝 週次AIレポート",    "✓",       "×"],
        ].map(([f, pro, free], i) => (
          <div key={i} style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr", gap: 4, padding: "9px 0", borderBottom: "1px solid #F3F4F6", alignItems: "center" }}>
            <span style={{ fontSize: 12, color: "#374151" }}>{f}</span>
            <span style={{ fontSize: 11, color: "#059669", fontWeight: 700, textAlign: "center" }}>{pro}</span>
            <span style={{ fontSize: 11, color: "#9CA3AF", textAlign: "center" }}>{free}</span>
          </div>
        ))}
        <div style={{ background: "linear-gradient(135deg,#FEF3C7,#FDE68A)", borderRadius: 12, padding: "10px 16px", marginTop: 20, marginBottom: 12, textAlign: "center" }}>
          <p style={{ fontSize: 13, fontWeight: 700, color: "#92400E" }}>🔥 今すぐ継続で年間4,500円！（通常6,000円）</p>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 20 }}>
          {SUBSCRIPTION_PLANS.map(plan => (
            <button key={plan.id} onClick={() => setSelectedPlan(plan.id)} style={{ padding: "14px 16px", borderRadius: 14, cursor: "pointer", textAlign: "left", fontFamily: "inherit", border: `2px solid ${plan.highlight ? "#F59E0B" : selectedPlan === plan.id ? "#059669" : "#E5E7EB"}`, background: plan.highlight ? (selectedPlan === plan.id ? "#FFFBEB" : "#FFFDE7") : selectedPlan === plan.id ? "#ECFDF5" : "#fff", position: "relative", overflow: "visible" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <div style={{ display: "flex", gap: 6, alignItems: "center", marginBottom: 2 }}>
                    <span style={{ fontSize: 14, fontWeight: 700, color: plan.highlight ? "#92400E" : "#111827" }}>{plan.name}</span>
                    {plan.badge && <span style={{ fontSize: 10, fontWeight: 700, color: "#fff", background: plan.highlight ? "#F59E0B" : "#EF4444", borderRadius: 6, padding: "2px 6px" }}>{plan.badge}</span>}
                  </div>
                  {plan.sub && <span style={{ fontSize: 11, color: plan.highlight ? "#D97706" : "#059669", fontWeight: 600 }}>{plan.sub}</span>}
                </div>
                <div style={{ textAlign: "right" }}>
                  <span style={{ fontSize: 18, fontWeight: 800, color: plan.highlight ? "#92400E" : "#111827" }}>{plan.price}</span>
                  <span style={{ fontSize: 11, color: "#6B7280" }}>{plan.period}</span>
                </div>
              </div>
            </button>
          ))}
        </div>
        <button onClick={handleSubscribe} disabled={loading} style={{ width: "100%", padding: "16px", borderRadius: 14, border: "none", background: "linear-gradient(135deg,#34D399,#059669)", color: "#fff", fontSize: 16, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", opacity: loading ? 0.7 : 1 }}>
          {loading ? "処理中..." : `${SUBSCRIPTION_PLANS.find(p => p.id === selectedPlan)?.price}プランを始める`}
        </button>
        <p style={{ fontSize: 11, color: "#9CA3AF", textAlign: "center", marginTop: 10, lineHeight: 1.6 }}>
          ※ これはUIデモです。実際の課金は発生しません
        </p>
        {!isExpired && onClose && (
          <button onClick={onClose} style={{ width: "100%", marginTop: 8, padding: "12px", borderRadius: 14, border: "none", background: "transparent", color: "#9CA3AF", fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>
            あとで（残り{trialLeft}日）
          </button>
        )}
      </div>
    </div>
  );
};

// ─── QUIT HABITS MODAL ────────────────────────────────────────────────────────
const QuitHabitsModal = ({ habits, onClose, onAdd, onCheck, onDelete, th, cs }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const todayStr = today();
  const cardBase = { background: th?.card || "#fff", borderRadius: cs?.radius || 14, boxShadow: cs?.shadow || "0 1px 4px rgba(0,0,0,0.06)", border: cs?.hasBorder ? `1.5px solid ${th?.border}` : "none" };

  const handleAdd = () => {
    if (!newTitle.trim()) return;
    onAdd({ id: `quit_${Date.now()}`, title: newTitle.trim(), streak: 0, lastChecked: null });
    setNewTitle(""); setShowAdd(false);
  };

  return (
    <div style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.5)", display: "flex", alignItems: "flex-end", zIndex: 300, animation: "fadeUp 0.2s ease" }} onClick={onClose}>
      <div style={{ width: "100%", background: th?.card || "#fff", borderRadius: "22px 22px 0 0", maxHeight: "82%", overflowY: "auto", padding: "24px 20px 48px" }} onClick={e => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 18 }}>
          <h3 style={{ fontSize: 18, fontWeight: 800, color: th?.text || "#111827" }}>🚫 やめること管理</h3>
          <button onClick={onClose} style={{ fontSize: 22, background: "none", border: "none", color: th?.subtext || "#9CA3AF", cursor: "pointer", lineHeight: 1 }}>×</button>
        </div>
        {habits.length === 0 && !showAdd && (
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <div style={{ fontSize: 36 }}>🚫</div>
            <p style={{ fontSize: 13, color: th?.subtext || "#9CA3AF", marginTop: 8 }}>やめたいことを登録しよう</p>
          </div>
        )}
        <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 14 }}>
          {habits.map(h => {
            const doneToday = h.lastChecked === todayStr;
            return (
              <div key={h.id} style={{ ...cardBase, padding: "13px 16px", display: "flex", alignItems: "center", gap: 12 }}>
                <button onClick={() => !doneToday && onCheck(h.id)} style={{ width: 30, height: 30, borderRadius: 99, border: `2px solid ${doneToday ? "#10B981" : (th?.border || "#E5E7EB")}`, background: doneToday ? "#10B981" : "transparent", cursor: doneToday ? "default" : "pointer", fontSize: 14, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  {doneToday ? "✓" : ""}
                </button>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <p style={{ fontSize: 14, fontWeight: 600, color: th?.text || "#111827", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{h.title}</p>
                  <p style={{ fontSize: 11, color: th?.subtext || "#6B7280", marginTop: 2 }}>🔥 {h.streak}日連続</p>
                </div>
                <button onClick={() => onDelete(h.id)} style={{ fontSize: 18, background: "none", border: "none", color: "#EF4444", cursor: "pointer", flexShrink: 0 }}>×</button>
              </div>
            );
          })}
        </div>
        {showAdd ? (
          <div style={{ ...cardBase, padding: "14px", marginBottom: 10 }}>
            <input value={newTitle} onChange={e => setNewTitle(e.target.value)} placeholder="例）SNSを1時間以上見ない"
              style={{ width: "100%", padding: "10px 12px", borderRadius: 10, border: `1.5px solid ${th?.border || "#E5E7EB"}`, background: th?.bg || "#F9FAFB", fontSize: 14, outline: "none", fontFamily: "inherit", color: th?.text || "#111827", boxSizing: "border-box", marginBottom: 10 }} />
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => setShowAdd(false)} style={{ flex: 1, padding: "10px", borderRadius: 10, border: `1.5px solid ${th?.border || "#E5E7EB"}`, background: "transparent", color: th?.subtext || "#6B7280", fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>キャンセル</button>
              <button onClick={handleAdd} disabled={!newTitle.trim()} style={{ flex: 1, padding: "10px", borderRadius: 10, border: "none", background: newTitle.trim() ? "linear-gradient(135deg,#34D399,#059669)" : "#E5E7EB", color: newTitle.trim() ? "#fff" : "#9CA3AF", fontSize: 13, fontWeight: 700, cursor: newTitle.trim() ? "pointer" : "default", fontFamily: "inherit" }}>追加する</button>
            </div>
          </div>
        ) : (
          <button onClick={() => setShowAdd(true)} style={{ width: "100%", padding: "12px", borderRadius: 12, border: `1.5px dashed ${th?.border || "#E5E7EB"}`, background: "transparent", color: th?.primary || "#059669", fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
            ＋ やめることを追加
          </button>
        )}
      </div>
    </div>
  );
};

// ─── Main App ──────────────────────────────────────────────────────────────────
export default function App() {
  const [screen,    setScreen]    = useState("home");
  const [todos,     setTodos]     = useState([]);
  const [editTodo,  setEditTodo]  = useState(null);
  const [situation, setSituation] = useState("仕事中");
  const [settings,  setSettings]  = useState({ notification: true, random: true, startTime: "08:00", endTime: "22:00", themeId: "natural", fontId: "rounded", cardStyleId: "rounded" });
  const [customCategories, setCustomCategories] = useState([]);
  const [catModal,  setCatModal]  = useState(null);

  const [user,         setUser]         = useState(null);
  const [authLoading,  setAuthLoading]  = useState(true);
  const [loading,      setLoading]      = useState(false);
  const [loginLoading, setLoginLoading] = useState(false);
  const [notifPermission, setNotifPermission] = useState(
    "Notification" in window ? Notification.permission : "unsupported"
  );
  const [fcmReady, setFcmReady] = useState(false);
  const swRegRef  = useRef(null);

  const [streak,             setStreak]             = useState({ current: 0, max: 0, lastDate: "" });
  const [unlockedRewards,    setUnlockedRewards]    = useState([]);
  const [rewardAnim,         setRewardAnim]         = useState(null);
  const [repeatDeleteModal,  setRepeatDeleteModal]  = useState(null);

  // New feature state
  const [profile,          setProfile]          = useState(null);
  const [showOnboarding,   setShowOnboarding]   = useState(false);
  const [onboardingReady,  setOnboardingReady]  = useState(false);
  const [dopamineScore,    setDopamineScore]    = useState(50);
  // eslint-disable-next-line no-unused-vars
  const [dopamineHistory,  setDopamineHistory]  = useState([]);
  const [quitHabits,       setQuitHabits]       = useState([]);
  const [aiSuggestions,    setAiSuggestions]    = useState([]);
  const [confettiActive,   setConfettiActive]   = useState(false);
  const [praiseMsg,        setPraiseMsg]        = useState("");
  const [subscription,     setSubscription]     = useState(null);
  const [showPaywall,      setShowPaywall]      = useState(false);
  const [quitHabitsModal,  setQuitHabitsModal]  = useState(false);

  // Folder state
  const [folders,          setFolders]          = useState([]);
  const [currentFolder,    setCurrentFolder]    = useState(null);
  const [showFolderCreate, setShowFolderCreate] = useState(false);
  const [editingFolder,    setEditingFolder]    = useState(null);
  const [showSimpleAdd,    setShowSimpleAdd]    = useState(false);

  const allCategories    = customCategories;
  const th               = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
  const af               = APP_FONTS.find(f => f.id === settings.fontId) || APP_FONTS[0];
  const cs               = CARD_STYLES.find(c => c.id === settings.cardStyleId) || CARD_STYLES[0];
  const unlockedThemeIds = REWARDS.filter(r => unlockedRewards.includes(r.id) && r.themeId).map(r => r.themeId);

  // AIサジェストをプロフィールがロードされたら1日1回取得
  useEffect(() => {
    if (!profile || aiSuggestions.length > 0) return;
    fetchAISuggestions(profile);
  }, [profile]); // eslint-disable-line react-hooks/exhaustive-deps

  // Service Worker 登録
  useEffect(() => {
    if (!("serviceWorker" in navigator)) return;
    navigator.serviceWorker.register(`${process.env.PUBLIC_URL}/firebase-messaging-sw.js`)
      .then(reg => { swRegRef.current = reg; })
      .catch(() => {});
  }, []);

  // 認証監視
  useEffect(() => {
    return onAuthStateChanged(auth, u => { setUser(u); setAuthLoading(false); });
  }, []);

  // todos リアルタイム同期
  useEffect(() => {
    if (!user) { setTodos([]); setLoading(false); return; }
    setLoading(true);
    const q = query(collection(db, "users", user.uid, "todos"), orderBy("createdAt", "asc"));
    return onSnapshot(q, snap => {
      setTodos(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setLoading(false);
    }, () => setLoading(false));
  }, [user]);

  // カスタムカテゴリ + テーマ + ストリーク + 特典 + 新機能データ の読み込み
  useEffect(() => {
    if (!user) {
      setCustomCategories([]); setStreak({ current: 0, max: 0, lastDate: "" }); setUnlockedRewards([]);
      setProfile(null); setDopamineScore(50); setDopamineHistory([]); setQuitHabits([]); setAiSuggestions([]);
      setSubscription(null); setShowOnboarding(false); setOnboardingReady(false); setFolders([]); setCurrentFolder(null);
      return;
    }
    return onSnapshot(doc(db, "users", user.uid), snap => {
      if (snap.exists()) {
        const data = snap.data();
        setCustomCategories(data.customCategories || []);
        // カテゴリ → フォルダ 移行（初回のみ）
        if ((data.customCategories || []).length > 0 && !(data.categoryMigrated)) {
          const existing = data.folders || [];
          const migratedIds = new Set(existing.map(f => f.id));
          const newFolders = (data.customCategories || [])
            .filter(c => !migratedIds.has(c.id))
            .map((c, i) => ({ id: c.id, name: c.label || c.id, emoji: c.emoji || "📁", color: FOLDER_COLORS[i % FOLDER_COLORS.length].color, subfolders: [], order: existing.length + i }));
          if (newFolders.length > 0) {
            const merged = [...existing, ...newFolders];
            setDoc(doc(db, "users", user.uid), { folders: merged, categoryMigrated: true }, { merge: true });
          } else {
            setDoc(doc(db, "users", user.uid), { categoryMigrated: true }, { merge: true });
          }
        }
        const ap = data.appearance;
        if (ap) setSettings(s => ({ ...s, themeId: ap.themeId || s.themeId, fontId: ap.fontId || s.fontId, cardStyleId: ap.cardStyleId || s.cardStyleId }));
        if (data.streak) setStreak(data.streak);
        if (data.unlockedRewards) setUnlockedRewards(data.unlockedRewards);

        // New feature data
        if (data.profile) { setProfile(data.profile); setShowOnboarding(false); }
        else { setShowOnboarding(true); }
        setOnboardingReady(true);

        if (typeof data.dopamineScore === "number") setDopamineScore(data.dopamineScore);
        if (data.dopamineHistory) setDopamineHistory(data.dopamineHistory);
        if (data.quitHabits) setQuitHabits(data.quitHabits);
        if (data.aiSuggestions?.date === today()) setAiSuggestions(data.aiSuggestions.todos || []);
        if (data.folders) setFolders(data.folders);

        // Subscription / trial
        const sub = data.subscription || {};
        if (!sub.startDate) {
          const newSub = { startDate: today(), plan: null };
          setDoc(doc(db, "users", user.uid), { subscription: newSub }, { merge: true });
          setSubscription(newSub);
        } else {
          setSubscription(sub);
          if (!sub.plan) {
            const startD = new Date(sub.startDate + "T00:00:00");
            const trialEnd = new Date(startD); trialEnd.setDate(trialEnd.getDate() + 7);
            if (new Date(today() + "T00:00:00") > trialEnd) setShowPaywall(true);
          }
        }
      } else {
        // New user — show onboarding
        setShowOnboarding(true);
        setOnboardingReady(true);
        const newSub = { startDate: today(), plan: null };
        setDoc(doc(db, "users", user.uid), { subscription: newSub }, { merge: true });
        setSubscription(newSub);
      }
    });
  }, [user]);

  // テーマ変更をFirestoreに保存
  const handleAppearanceChange = async (key, value) => {
    const next = { ...settings, [key]: value };
    setSettings(next);
    if (user) await setDoc(doc(db, "users", user.uid), { appearance: { themeId: next.themeId, fontId: next.fontId, cardStyleId: next.cardStyleId } }, { merge: true });
  };

  // ストリーク更新 + 称号解放チェック
  const updateStreak = async () => {
    const todayStr = today();
    if (streak.lastDate === todayStr) return;

    const d = new Date(todayStr + "T00:00:00");
    d.setDate(d.getDate() - 1);
    const yesterdayStr = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;

    const isChain  = streak.lastDate === yesterdayStr || !streak.lastDate;
    const newCurrent = isChain ? (streak.current || 0) + 1 : 1;
    const newMax     = Math.max(streak.max || 0, newCurrent);
    const newStreak  = { current: newCurrent, max: newMax, lastDate: todayStr };
    setStreak(newStreak);

    const newlyUnlocked = REWARDS
      .filter(r => newCurrent >= r.days && !unlockedRewards.includes(r.id))
      .map(r => r.id);

    const allUnlocked = newlyUnlocked.length > 0 ? [...unlockedRewards, ...newlyUnlocked] : unlockedRewards;
    if (newlyUnlocked.length > 0) {
      setUnlockedRewards(allUnlocked);
      const top = REWARDS.filter(r => newlyUnlocked.includes(r.id)).sort((a, b) => b.days - a.days)[0];
      setRewardAnim(top);
      if (newlyUnlocked.includes("streak_365") && user) {
        await setDoc(doc(db, "hallOfFame", user.uid), {
          displayName: user.displayName || user.email?.split("@")[0] || "匿名",
          date: todayStr, uid: user.uid,
        });
      }
    }

    if (user) {
      await setDoc(doc(db, "users", user.uid), {
        streak: newStreak,
        ...(newlyUnlocked.length > 0 ? { unlockedRewards: allUnlocked } : {}),
      }, { merge: true });
    }
  };

  // FCMトークン取得・Firestoreに保存
  useEffect(() => {
    if (!user || notifPermission !== "granted" || !swRegRef.current) return;
    const vapidKey = process.env.REACT_APP_FIREBASE_VAPID_KEY;
    if (!vapidKey) return;
    (async () => {
      try {
        const messaging = await getMessagingInstance();
        if (!messaging) return;
        const token = await getToken(messaging, { vapidKey, serviceWorkerRegistration: swRegRef.current });
        if (!token) return;
        await setDoc(doc(db, "users", user.uid), { fcmToken: token, fcmUpdatedAt: Date.now() }, { merge: true });
        setFcmReady(true);
        // フォアグラウンドのFCMメッセージを処理
        onMessage(messaging, payload => {
          const n = payload.notification || {};
          if ("Notification" in window && Notification.permission === "granted") {
            new Notification(n.title || "TODO LIFE ✅", { body: n.body || "", icon: "/logo192.png", tag: "todo-life-fg" });
          }
        });
      } catch {}
    })();
  }, [user, notifPermission]);

  // 旧フォーマット（done:true + nextDue）を completedDates 形式に移行
  useEffect(() => {
    if (!user || todos.length === 0) return;
    todos.filter(t => t.done && t.repeat && t.repeat !== "none").forEach(async t => {
      const prev = t.completedDates || [];
      const lastDate = t.deadline || today();
      const next = prev.includes(lastDate) ? prev : [...prev, lastDate];
      await updateDoc(doc(db, "users", user.uid, "todos", t.id), { done: false, nextDue: null, completedDates: next });
    });
  }, [todos, user]);

  // 通知許可 + FCMトークン取得
  const requestNotifPermission = async () => {
    if (!("Notification" in window)) return;
    const perm = await Notification.requestPermission();
    setNotifPermission(perm);
  };

  // ランダム通知スケジューラー
  useEffect(() => {
    if (!settings.notification || !settings.random || !user || notifPermission !== "granted") return;
    let tid;
    const schedule = () => {
      const now = new Date();
      const [sH, sM] = settings.startTime.split(":").map(Number);
      const [eH, eM] = settings.endTime.split(":").map(Number);
      const nowMin = now.getHours() * 60 + now.getMinutes();
      const endMin = eH * 60 + eM;
      if (nowMin < sH * 60 + sM || nowMin >= endMin) return;
      const remaining = endMin - nowMin;
      const maxD = Math.min(120, remaining - 1);
      const minD = Math.min(30, maxD);
      if (maxD <= 0) return;
      tid = setTimeout(() => {
        const undone = todos.filter(t => !isTodoDone(t));
        const body = undone.length > 0
          ? (() => { const t = undone[Math.floor(Math.random() * undone.length)]; return t.title; })()
          : "今日のTODOは全て完了しています！🎉";
        new Notification("TODO LIFE ✅", { body, icon: "/logo192.png", tag: "todo-life-reminder" });
        schedule();
      }, (minD + Math.random() * (maxD - minD)) * 60 * 1000);
    };
    schedule();
    return () => clearTimeout(tid);
  }, [settings.notification, settings.random, settings.startTime, settings.endTime, notifPermission, todos, user]);

  // SWへ通知スケジュールを送信（バックグラウンド通知用）
  useEffect(() => {
    if (!settings.notification || !settings.random || !user || !swRegRef.current) return;
    const undone = todos.filter(t => !isTodoDone(t));
    if (undone.length === 0) return;
    const [eH, eM] = settings.endTime.split(":").map(Number);
    const endMs = new Date();
    endMs.setHours(eH, eM, 0, 0);
    if (Date.now() >= endMs.getTime()) return;
    const sw = swRegRef.current.active || swRegRef.current.installing || swRegRef.current.waiting;
    sw?.postMessage({
      type: "SCHEDULE_NOTIFS",
      todos: undone.map(t => t.title),
      endMs: endMs.getTime(),
    });
  }, [todos, settings.notification, settings.random, settings.endTime, user]);

  // CRUD
  const handleToggle = async (id, occurrenceDate = null) => {
    if (!user) return;
    const todo = todos.find(t => t.id === id);
    if (!todo) return;
    let isMarkingDone = false;
    if (todo.repeat && todo.repeat !== "none") {
      const dateKey = occurrenceDate || today();
      const prev = todo.completedDates || [];
      const wasDone = prev.includes(dateKey);
      isMarkingDone = !wasDone;
      const next = wasDone ? prev.filter(d => d !== dateKey) : [...prev, dateKey];
      await updateDoc(doc(db, "users", user.uid, "todos", id), { completedDates: next, done: false, nextDue: null });
    } else {
      isMarkingDone = !todo.done;
      await updateDoc(doc(db, "users", user.uid, "todos", id), { done: !todo.done, doneDate: !todo.done ? today() : null });
    }
    if (isMarkingDone) {
      await updateStreak();
      await updateDopamineScore(+10);
      setConfettiActive(true);
      setPraiseMsg(PRAISE_MESSAGES[Math.floor(Math.random() * PRAISE_MESSAGES.length)]);
    }
  };

  const handleSubtaskToggle = async (todoId, subtaskId) => {
    if (!user) return;
    const todo = todos.find(t => t.id === todoId);
    if (!todo) return;
    const updated = (todo.subtasks || []).map(st =>
      st.id === subtaskId ? { ...st, done: !st.done } : st
    );
    await updateDoc(doc(db, "users", user.uid, "todos", todoId), { subtasks: updated });
  };

  const handleDelete = async (id) => {
    if (!user) return;
    await deleteDoc(doc(db, "users", user.uid, "todos", id));
  };

  const handleRepeatDeleteDay = async (id, date) => {
    if (!user) return;
    const todo = todos.find(t => t.id === id);
    if (!todo) return;
    const excluded = [...(todo.excludedDates || [])];
    if (!excluded.includes(date)) excluded.push(date);
    await updateDoc(doc(db, "users", user.uid, "todos", id), { excludedDates: excluded });
  };

  const handleRepeatDeleteFrom = async (id, date) => {
    if (!user) return;
    await updateDoc(doc(db, "users", user.uid, "todos", id), { repeatEndDate: date });
  };

  const openRepeatDeleteModal = (todo, targetDate) => {
    setRepeatDeleteModal({ todo, targetDate });
  };

  // Dopamine score
  const updateDopamineScore = async (delta) => {
    setDopamineScore(prev => {
      const next = Math.max(0, Math.min(100, prev + delta));
      const todayStr = today();
      setDopamineHistory(hist => {
        const updated = [...hist.filter(h => h.date !== todayStr), { date: todayStr, score: next }].slice(-30);
        if (user) setDoc(doc(db, "users", user.uid), { dopamineScore: next, dopamineHistory: updated }, { merge: true });
        return updated;
      });
      return next;
    });
  };

  // Quit habits
  const handleAddQuitHabit = async (habit) => {
    const updated = [...quitHabits, habit];
    setQuitHabits(updated);
    if (user) await setDoc(doc(db, "users", user.uid), { quitHabits: updated }, { merge: true });
  };

  const handleCheckQuitHabit = async (habitId) => {
    const todayStr = today();
    const updated = quitHabits.map(h => {
      if (h.id !== habitId) return h;
      const d = new Date(); d.setDate(d.getDate() - 1);
      const yest = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
      const isChain = h.lastChecked === yest || !h.lastChecked;
      return { ...h, lastChecked: todayStr, streak: isChain ? (h.streak || 0) + 1 : 1 };
    });
    setQuitHabits(updated);
    if (user) await setDoc(doc(db, "users", user.uid), { quitHabits: updated }, { merge: true });
    await updateDopamineScore(+10);
  };

  const handleDeleteQuitHabit = async (habitId) => {
    const updated = quitHabits.filter(h => h.id !== habitId);
    setQuitHabits(updated);
    if (user) await setDoc(doc(db, "users", user.uid), { quitHabits: updated }, { merge: true });
  };

  // Folder CRUD
  const handleAddFolder = async (data) => {
    const newFolder = { ...data, id: `folder_${Date.now()}`, subfolders: [], order: folders.length };
    const updated = [...folders, newFolder];
    setFolders(updated);
    if (user) await setDoc(doc(db, "users", user.uid), { folders: updated }, { merge: true });
    setShowFolderCreate(false);
  };

  const handleEditFolder = async (data) => {
    const updated = folders.map(f => f.id === editingFolder.id ? { ...f, ...data } : f);
    setFolders(updated);
    setCurrentFolder(prev => prev?.id === editingFolder.id ? { ...prev, ...data } : prev);
    if (user) await setDoc(doc(db, "users", user.uid), { folders: updated }, { merge: true });
    setEditingFolder(null); setShowFolderCreate(false);
  };

  const handleDeleteFolder = async (folderId) => {
    const folderTodos = todos.filter(t => t.folderId === folderId);
    await Promise.all(folderTodos.map(t => user ? updateDoc(doc(db, "users", user.uid, "todos", t.id), { folderId: null, subfolderId: null }) : Promise.resolve()));
    const updated = folders.filter(f => f.id !== folderId);
    setFolders(updated);
    setCurrentFolder(null);
    if (user) await setDoc(doc(db, "users", user.uid), { folders: updated }, { merge: true });
  };

  const handleAddSubfolder = async (folderId, subData) => {
    const updated = folders.map(f => {
      if (f.id !== folderId) return f;
      const sub = { ...subData, id: `sub_${Date.now()}`, order: (f.subfolders || []).length };
      return { ...f, subfolders: [...(f.subfolders || []), sub] };
    });
    setFolders(updated);
    setCurrentFolder(updated.find(f => f.id === folderId) || null);
    if (user) await setDoc(doc(db, "users", user.uid), { folders: updated }, { merge: true });
  };

  // AI suggestions
  const fetchAISuggestions = async (prof) => {
    const apiKey = process.env.REACT_APP_ANTHROPIC_API_KEY;
    if (!apiKey || !prof) return;
    try {
      const prompt = `あなたはTODOアプリのAIアシスタントです。\nユーザー:\n- 課題: ${(prof.issues||[]).join("、")}\n- 目標: ${(prof.goals||[]).join("、")}\n- タイプ: ${prof.diagnosis||"不明"}\n\n今日取り組むべきTODOを3〜5個提案してください。JSON: {"todos":[{"title":"タスク名","reason":"理由（短く）"}]}`;
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-api-key": apiKey,
          "anthropic-version": "2023-06-01",
          "anthropic-dangerous-direct-browser-access": "true",
        },
        body: JSON.stringify({ model: "claude-haiku-4-5-20251001", max_tokens: 500, messages: [{ role: "user", content: prompt }] }),
      });
      if (!res.ok) return;
      const data = await res.json();
      const text = data.content?.[0]?.text || "";
      const match = text.match(/\{[\s\S]*\}/);
      if (!match) return;
      const parsed = JSON.parse(match[0]);
      const todos = parsed.todos || [];
      setAiSuggestions(todos);
      if (user) await setDoc(doc(db, "users", user.uid), { aiSuggestions: { date: today(), todos } }, { merge: true });
    } catch {}
  };

  // eslint-disable-next-line no-unused-vars
  const handleAddAISuggestion = async (suggestion) => {
    if (!user) return;
    await addDoc(collection(db, "users", user.uid, "todos"), {
      title: suggestion.title, deadline: "", deadlineTime: "",
      category: customCategories[0]?.id || "", memo: suggestion.reason || "",
      repeat: "none", repeatTime: "", subtasks: [], done: false, createdAt: Date.now(),
    });
    setAiSuggestions(prev => prev.filter(s => s.title !== suggestion.title));
  };

  // Onboarding completion
  const handleOnboardingComplete = async (prof, suggestedTodos) => {
    setProfile(prof);
    setShowOnboarding(false);
    for (const title of suggestedTodos) {
      if (!user) break;
      await addDoc(collection(db, "users", user.uid, "todos"), {
        title, deadline: "", deadlineTime: "", category: customCategories[0]?.id || "",
        memo: "", repeat: "none", repeatTime: "", subtasks: [], done: false, createdAt: Date.now(),
      });
    }
    if (prof && process.env.REACT_APP_ANTHROPIC_API_KEY) setTimeout(() => fetchAISuggestions(prof), 600);
  };

  // Subscription
  const trialEndDate = (() => {
    if (!subscription?.startDate) return null;
    const d = new Date(subscription.startDate + "T00:00:00");
    d.setDate(d.getDate() + 7);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  })();

  const handleSelectPlan = async (plan) => {
    const next = { ...(subscription || {}), plan };
    setSubscription(next);
    setShowPaywall(false);
    if (user) await setDoc(doc(db, "users", user.uid), { subscription: next }, { merge: true });
  };

  const handleSave = async (data, editId) => {
    if (!user) return;
    if (editId) {
      await updateDoc(doc(db, "users", user.uid, "todos", editId), data);
    } else {
      await addDoc(collection(db, "users", user.uid, "todos"), { ...data, done: false, createdAt: Date.now() });
    }
  };

  const handleQuickAdd = async (title) => {
    if (!user || !title.trim()) return;
    await addDoc(collection(db, "users", user.uid, "todos"), { title: title.trim(), deadline: "", deadlineTime: "", category: customCategories[0]?.id || "", memo: "", repeat: "none", repeatTime: "", subtasks: [], done: false, createdAt: Date.now() });
  };

  // カスタムカテゴリ
  const handleAddCategory = async (cat) => {
    if (customCategories.length >= 20) return;
    const updated = [...customCategories, cat];
    setCustomCategories(updated);
    if (user) await setDoc(doc(db, "users", user.uid), { customCategories: updated }, { merge: true });
  };

  const handleEditCategory = async (cat) => {
    const updated = customCategories.map(c => c.id === cat.id ? cat : c);
    setCustomCategories(updated);
    if (user) await setDoc(doc(db, "users", user.uid), { customCategories: updated }, { merge: true });
  };

  const handleDeleteCategory = async (catId) => { // eslint-disable-line no-unused-vars
    const updated = customCategories.filter(c => c.id !== catId);
    setCustomCategories(updated);
    if (user) await setDoc(doc(db, "users", user.uid), { customCategories: updated }, { merge: true });
  };

  const openCatModal = (cb = null, editCat = null) => setCatModal({
    onSave: typeof cb === "function" ? cb : () => {},
    editCat: editCat || null,
    isEdit: !!editCat,
  });

  // ナビゲーション
  const navItems = [
    { id: "home",        emoji: "🏠", label: "ホーム" },
    { id: "growthGraph", emoji: "📊", label: "グラフ" },
    { id: "add",         emoji: "＋", label: "" },
    { id: "calendar",    emoji: "📅", label: "カレンダー" },
    { id: "settings",    emoji: "⚙️", label: "設定" },
  ];

  const handleNav = (id) => {
    if (id === "add") { setShowSimpleAdd(true); return; }
    setScreen(id);
  };

  const renderScreen = () => {
    if (onboardingReady && showOnboarding) return <OnboardingScreen onComplete={handleOnboardingComplete} user={user} />;
    if (showPaywall && trialEndDate) return <PaywallScreen trialEndDate={trialEndDate} onClose={() => setShowPaywall(false)} onSelectPlan={handleSelectPlan} th={th} />;
    if (currentFolder) return <FolderScreen folder={currentFolder} todos={todos} setScreen={setScreen} setEditTodo={setEditTodo} onToggle={handleToggle} onBack={() => setCurrentFolder(null)} onAddSubfolder={handleAddSubfolder} th={th} cs={cs} />;
    switch (screen) {
      case "home":      return <HomeScreen todos={todos} folders={folders} dopamineScore={dopamineScore} setScreen={setScreen} setEditTodo={setEditTodo} onToggle={handleToggle} onDelete={handleDelete} onCreateFolder={() => { setEditingFolder(null); setShowFolderCreate(true); }} th={th} cs={cs} />;
      case "community": return <CommunityScreen th={th} />;
      case "add":       return <AddScreen setScreen={setScreen} editTodo={editTodo} onSave={handleSave} onAddExtra={handleQuickAdd} categories={allCategories} openCatModal={openCatModal} folders={folders} th={th} cs={cs} />;
      case "situation": return <SituationScreen setScreen={setScreen} setSituation={setSituation} categories={allCategories} th={th} cs={cs} />;
      case "recommend": return <RecommendScreen todos={todos} situation={situation} setScreen={setScreen} setEditTodo={setEditTodo} onToggle={handleToggle} categories={allCategories} th={th} cs={cs} />;
      case "list":      return <ListScreen todos={todos} setScreen={setScreen} setEditTodo={setEditTodo} onToggle={handleToggle} onDelete={handleDelete} onRepeatDelete={openRepeatDeleteModal} categories={allCategories} th={th} cs={cs} />;
      case "detail":    return <DetailScreen todo={editTodo} setScreen={setScreen} setEditTodo={setEditTodo} onToggle={handleToggle} onSubtaskToggle={handleSubtaskToggle} onDelete={handleDelete} onRepeatDelete={openRepeatDeleteModal} categories={allCategories} th={th} cs={cs} />;
      case "calendar":  return <CalendarScreen todos={todos} setScreen={setScreen} setEditTodo={setEditTodo} onToggle={handleToggle} categories={allCategories} th={th} cs={cs} />;
      case "completedHistory": return <CompletedHistoryScreen todos={todos} setScreen={setScreen} th={th} cs={cs} />;
      case "growthGraph": return <GrowthGraphScreen todos={todos} streak={streak} setScreen={setScreen} th={th} cs={cs} />;
      case "notificationSettings": return <NotificationSettingsScreen settings={settings} setSettings={setSettings} notifPermission={notifPermission} onRequestPermission={requestNotifPermission} fcmReady={fcmReady} th={th} cs={cs} setScreen={setScreen} />;
      case "themeSettings": return <ThemeSettingsScreen settings={settings} th={th} cs={cs} onAppearanceChange={handleAppearanceChange} unlockedThemeIds={unlockedThemeIds} setScreen={setScreen} />;
      case "folderManagement": return <FolderManagementScreen folders={folders} onFolderAdd={() => { setEditingFolder(null); setShowFolderCreate(true); }} onFolderEdit={(f) => { setEditingFolder(f); setShowFolderCreate(true); }} onFolderDelete={handleDeleteFolder} th={th} cs={cs} setScreen={setScreen} />;
      case "about": return <AboutScreen th={th} cs={cs} setScreen={setScreen} />;
      case "settings": return <SettingsScreen user={user} onLogout={async () => { await signOut(auth); setScreen("home"); }} settings={settings} th={th} cs={cs} setScreen={setScreen} unlockedRewards={unlockedRewards} streak={streak} />;
      case "rewards":   return <RewardsScreen setScreen={setScreen} streak={streak} unlockedRewards={unlockedRewards} user={user} th={th} cs={cs} />;
      case "hallOfFame": return <HallOfFameScreen setScreen={setScreen} th={th} cs={cs} />;
      default:          return null;
    }
  };

  return (
    <div style={{ fontFamily: af.family, background: th.bg, minHeight: "100vh", display: "flex", justifyContent: "center", alignItems: "center" }}>
      <style>{`
        * { margin: 0; padding: 0; box-sizing: border-box; }
        @keyframes fadeUp      { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes slideIn     { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: translateX(0); } }
        @keyframes spin        { to { transform: rotate(360deg); } }
        @keyframes pulse       { 0%,100% { opacity: 1; } 50% { opacity: 0.6; } }
        @keyframes confettiFall { from { transform: translateY(-20px) rotate(0deg); opacity: 1; } to { transform: translateY(900px) rotate(720deg); opacity: 0; } }
        @keyframes praisePopUp { from { opacity: 0; transform: scale(0.7); } to { opacity: 1; transform: scale(1); } }
        ::-webkit-scrollbar { display: none; }
        input[type=date]::-webkit-inner-spin-button,
        input[type=date]::-webkit-calendar-picker-indicator { opacity: 0.5; }
        button:active { opacity: 0.8; }
        .dark-theme p,.dark-theme span,.dark-theme h1,.dark-theme h2,.dark-theme h3,.dark-theme label,.dark-theme a { color: #F9FAFB !important; }
        .dark-theme .subtext { color: #9CA3AF !important; }
        .dark-theme input,.dark-theme textarea,.dark-theme select { color: #F9FAFB !important; background: #374151 !important; border-color: #4B5563 !important; }
        .dark-theme input::placeholder,.dark-theme textarea::placeholder { color: #6B7280 !important; }
      `}</style>

      {/* Phone frame */}
      <div className={th.dark ? "dark-theme" : ""} style={{ width: "min(390px, 100vw)", height: "min(844px, 100vh)", background: th.bg, borderRadius: "min(44px, 0px)", overflow: "hidden", display: "flex", flexDirection: "column", position: "relative", boxShadow: "0 40px 120px rgba(0,0,0,0.2), 0 0 0 1px rgba(0,0,0,0.08)", fontFamily: af.family }}>

        {authLoading ? (
          <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <div style={{ width: 36, height: 36, borderRadius: 99, border: "3px solid #E5E7EB", borderTopColor: "#059669", animation: "spin 0.8s linear infinite" }} />
          </div>
        ) : !user ? (
          <LoginScreen
            onLogin={async () => { setLoginLoading(true); try { await signInWithPopup(auth, googleProvider); } catch(e) { console.error(e); } finally { setLoginLoading(false); } }}
            loginLoading={loginLoading}
          />
        ) : loading ? (
          <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 12 }}>
            <div style={{ width: 36, height: 36, borderRadius: 99, border: "3px solid #E5E7EB", borderTopColor: "#059669", animation: "spin 0.8s linear infinite" }} />
            <p style={{ fontSize: 13, color: "#9CA3AF" }}>データを読み込み中...</p>
          </div>
        ) : (
          <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden", animation: "slideIn 0.25s ease both" }} key={screen}>
            {renderScreen()}
          </div>
        )}

        {/* Bottom Nav */}
        {!authLoading && user && (
          <div style={{ height: 82, background: "#fff", borderTop: "1px solid #F3F4F6", display: "flex", alignItems: "center", paddingBottom: 10, flexShrink: 0, boxShadow: "0 -2px 16px rgba(0,0,0,0.06)" }}>
            {navItems.map(item => {
              const isActive = screen === item.id;
              const isAdd    = item.id === "add";
              return (
                <button key={item.id} onClick={() => handleNav(item.id)} style={{ flex: 1, height: "100%", background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3 }}>
                  {isAdd ? (
                    <div style={{ width: 52, height: 52, borderRadius: 16, marginTop: -24, background: "linear-gradient(135deg,#34D399,#059669)", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 6px 20px rgba(5,150,105,0.45)", fontSize: 26, color: "#fff", fontWeight: 700 }}>＋</div>
                  ) : (
                    <>
                      <span style={{ fontSize: 22, lineHeight: 1, filter: isActive ? "none" : "grayscale(0.4) opacity(0.5)" }}>{item.emoji}</span>
                      <span style={{ fontSize: 10, fontWeight: isActive ? 700 : 500, color: isActive ? "#059669" : "#ADADAD" }}>{item.label}</span>
                    </>
                  )}
                </button>
              );
            })}
          </div>
        )}

        {/* Category Creator Modal */}
        {catModal && (
          <CategoryCreatorModal
            editCat={catModal.editCat}
            onSave={cat => {
              if (catModal.isEdit) handleEditCategory(cat);
              else handleAddCategory(cat);
              catModal.onSave(cat);
              setCatModal(null);
            }}
            onClose={() => setCatModal(null)}
          />
        )}

        {/* Reward Unlock Modal */}
        <RewardUnlockModal reward={rewardAnim} onClose={() => setRewardAnim(null)} />

        {/* Confetti + Praise */}
        <ConfettiAnimation active={confettiActive} onDone={() => setConfettiActive(false)} />
        <PraiseToast message={praiseMsg} onDone={() => setPraiseMsg("")} />

        {/* Quit Habits Modal */}
        {quitHabitsModal && (
          <QuitHabitsModal
            habits={quitHabits}
            onClose={() => setQuitHabitsModal(false)}
            onAdd={handleAddQuitHabit}
            onCheck={handleCheckQuitHabit}
            onDelete={handleDeleteQuitHabit}
            th={th} cs={cs}
          />
        )}

        {/* Repeat Delete Modal */}
        {repeatDeleteModal && (
          <RepeatDeleteModal
            todo={repeatDeleteModal.todo}
            targetDate={repeatDeleteModal.targetDate}
            onClose={() => setRepeatDeleteModal(null)}
            onDeleteDay={(id, date) => { handleRepeatDeleteDay(id, date); setRepeatDeleteModal(null); if (screen === "detail") setScreen("list"); }}
            onDeleteFrom={(id, date) => { handleRepeatDeleteFrom(id, date); setRepeatDeleteModal(null); if (screen === "detail") setScreen("list"); }}
            onDeleteAll={(id) => { handleDelete(id); setRepeatDeleteModal(null); if (screen === "detail") setScreen("list"); }}
            th={th}
            cs={cs}
          />
        )}

        {/* Simple Add Modal (FAB) */}
        {showSimpleAdd && (
          <SimpleAddModal
            folders={folders}
            categories={allCategories}
            openCatModal={openCatModal}
            onAdd={async ({ title, deadline, deadlineTime, folderId, subfolderId, category, memo, repeat, repeatTime, subtasks }) => {
              if (!user || !title.trim()) return;
              await addDoc(collection(db, "users", user.uid, "todos"), {
                title, deadline: deadline || "", deadlineTime: deadline ? (deadlineTime || "") : "",
                category: category || allCategories[0]?.id || "",
                memo: memo || "", repeat: repeat || "none", repeatTime: repeatTime || "",
                subtasks: subtasks || [], done: false, createdAt: Date.now(),
                folderId: folderId || null, subfolderId: subfolderId || null,
              });
            }}
            onClose={() => setShowSimpleAdd(false)}
            th={th}
          />
        )}

        {/* Folder Create/Edit Modal */}
        {showFolderCreate && (
          <FolderCreateModal
            editFolder={editingFolder}
            onSave={editingFolder ? handleEditFolder : handleAddFolder}
            onClose={() => { setShowFolderCreate(false); setEditingFolder(null); }}
            th={th} cs={cs}
          />
        )}
      </div>
    </div>
  );
}
